// 物語（STORIES）― 人物の一生を地図でたどる（kind: 'person'）。書き方は docs/DATA_SPEC.md の 5・8・12 を参照。
// 場面は S(年, 見出し, 地名, 経度, 緯度, 横幅, 人物, 国, 要点, 語り, {marks, routes, lines, date}) で書き、DATA_SPEC の形に組み立てる。
(function () {
  function S(year, title, place, lon, lat, span, people, polities, text, talk, extra) {
    var st = { year: year, title: title, text: text, talk: talk, place: place, lon: lon, lat: lat, span: span };
    if (people && people.length) st.people = people;
    if (polities && polities.length) st.polities = polities;
    var x = extra || {};
    ['date', 'marks', 'routes', 'lines'].forEach(function (k) { if (x[k]) st[k] = x[k]; });
    return st;
  }
  window.STORIES = (window.STORIES || []).concat([
// ---------- アレクサンドロス大王 ----------
{
  id: 'life-alexander', kind: 'person', person: 'alexander', title: 'アレクサンドロス大王の生涯', period: '前356〜前323年',
  region: 'europe', view: 'westasia', tags: ['tankyu'],
  summary: 'マケドニアの王子として生まれ、アリストテレスに学び、20歳で王となったアレクサンドロスは、わずか10年あまりでギリシアからインダス川までを征服した。その足どりを追いながら、彼が何を夢見て、なぜ東へ進みつづけ、そしてなぜ32歳で倒れたのかを考える。',
  steps: [
    S(-356, 'ペラに生まれた王子', 'ペラ', 22.52, 40.76, 4, ['alexander'], ['macedon'],
      'マケドニア王フィリッポス2世と王妃オリュンピアスの子として、都ペラに生まれた。少年時代、だれも乗りこなせない暴れ馬ブケファラスが自分の影におびえていると見ぬき、太陽に向けて乗りこなしたと伝えられる。',
      '物語は紀元前356年、ギリシアの北にあるマケドニアの都ペラから始まります。王子アレクサンドロスの父は、軍を強くしてギリシアをうかがう王フィリッポス2世でした。少年時代、だれも乗れない暴れ馬を、馬が自分の影をこわがっていると見ぬいて乗りこなしたと伝えられています。この馬ブケファラスは、のちにインドまで彼を乗せていきます。',
      { marks: [{ name: 'アイガイ（旧都）', lon: 22.32, lat: 40.48 }] }),
    S(-343, 'アリストテレスの教え', 'ミエザ', 22.08, 40.64, 3, ['alexander', 'aristotle'], ['macedon'],
      '13歳のころ、父は哲学者アリストテレスを家庭教師に招き、ミエザの学園で学ばせた。王子は哲学や医学、ホメロスの詩を学び、英雄アキレウスにあこがれた。『イリアス』を遠征中も枕元に置いていたと伝えられる。',
      '13歳になった王子の先生に選ばれたのは、なんと哲学者アリストテレスでした。ペラの近くのミエザという静かな土地で、王子は仲間とともに哲学や医学、詩を学びます。とくに好きだったのはホメロスの詩、イリアスでした。英雄アキレウスのように生きたい。この思いは一生消えず、遠征中もこの本を枕元に置いていたと伝えられています。',
      { marks: [{ name: 'ペラ', lon: 22.52, lat: 40.76 }] }),
    S(-338, '18歳の初陣と父の死', 'カイロネイア', 22.84, 38.50, 5, ['alexander'], ['macedon', 'athens'],
      'カイロネイアの戦いで、18歳のアレクサンドロスは左翼の騎兵を率い、アテネ・テーベ連合軍を破った。2年後の前336年、父フィリッポスが護衛に暗殺され、20歳の王子が王位をついだ。',
      '紀元前338年、カイロネイアの戦いです。18歳のアレクサンドロスは騎兵を率いて敵の陣を突きくずし、父の勝利に大きく貢献しました。ところが2年後、父は娘の結婚式の場で護衛の一人に刺し殺されます。犯人の動機はよくわかっていません。20歳の若者は、反乱の動きを素早くおさえ、王の座を固めました。',
      { marks: [{ name: 'アテネ', lon: 23.73, lat: 37.98 }, { name: 'テーベ', lon: 23.32, lat: 38.32 }] }),
    S(-334, 'アジアへわたる', 'グラニコス川', 27.30, 40.25, 6, ['alexander'], ['alexander', 'achaemenid'],
      '前334年、約3万数千の兵を率いてヘレスポントス海峡をわたった。まずトロイアに立ち寄り、アキレウスの墓に花輪をささげたと伝えられる。グラニコス川の戦いでは自ら先頭に立って突撃し、あやうく命を落としかけた。',
      '紀元前334年、22歳の王はヘレスポントス海峡をわたり、アジアに入りました。最初に向かったのは、伝説の都トロイアです。あこがれのアキレウスの墓に花輪をささげたと伝えられています。グラニコス川の戦いでは、王みずから騎兵の先頭で川をわたりました。敵の刀が頭にふりおろされる寸前、部下のクレイトスが救ったといわれます。',
      { routes: [{ name: '遠征軍の進路', color: '#b8860b', pts: [[22.52, 40.76], [24.0, 40.9], [26.4, 40.2], [26.24, 39.96], [27.3, 40.25]] }],
        marks: [{ name: 'トロイア', lon: 26.24, lat: 39.96 }] }),
    S(-333, 'イッソスの戦い', 'イッソス', 36.20, 36.85, 6, ['alexander'], ['alexander', 'achaemenid'],
      'イッソスでペルシア王ダレイオス3世の大軍を破った。王は戦車で逃げ、母と妻子が陣に残された。アレクサンドロスは彼女たちを王族として丁重にあつかい、その態度は敵味方に強い印象を与えたと伝えられる。',
      '紀元前333年、地中海の東のすみ、イッソスで、ついにペルシア王ダレイオス3世と向き合います。アレクサンドロスは王のいる中央をめがけて突進し、ダレイオスは戦車をすてて逃げました。陣には王の母や妻、子どもが残されます。若い王は彼女たちを殺さず、王族として丁重にあつかいました。勝者の寛大さも、彼の武器の一つでした。',
      { routes: [{ name: '進軍', color: '#b8860b', pts: [[27.3, 40.25], [32.9, 39.6], [34.9, 37.0], [36.2, 36.85]] }],
        marks: [{ name: 'ゴルディオン', lon: 31.99, lat: 39.65 }] }),
    S(-331, 'エジプトとアレクサンドリア', 'アレクサンドリア', 29.92, 31.20, 8, ['alexander'], ['alexander'],
      'エジプトに入ると、人びとはペルシアからの解放者として迎えた。王は砂漠のシーワのアモン神殿をたずね、神の子と告げられたと伝えられる。地中海岸には、自分の名をつけた都市アレクサンドリアの建設を命じた。',
      'エジプトの人びとは、ペルシアの支配を終わらせた若い王を歓迎しました。王は危険をおかして西の砂漠を進み、シーワのオアシスにあるアモン神殿をたずねます。そこで神官から、あなたは神の子だと告げられたと伝えられています。そして地中海の岸に、自分の名をつけた都市の建設を命じました。のちに世界最大の図書館をもつ学問の都、アレクサンドリアです。',
      { marks: [{ name: 'シーワのアモン神殿', lon: 25.52, lat: 29.20 }, { name: 'メンフィス', lon: 31.25, lat: 29.85 }] }),
    S(-331, 'ガウガメラの決戦', 'ガウガメラ', 43.40, 36.60, 7, ['alexander'], ['alexander', 'achaemenid'],
      'ティグリス川の上流、ガウガメラ（アルベラ）でダレイオス3世との最後の決戦にのぞんだ。ペルシア軍は数倍の大軍だったが、王は敵の陣に生じたすきまを騎兵で突き、ふたたびダレイオスを敗走させた。',
      '紀元前331年の秋、ティグリス川の上流のガウガメラで、決戦が行われました。ペルシア軍は兵の数で何倍も上回り、車輪に刃をつけた戦車まで用意していました。前の晩、夜襲をすすめる部下に、王は勝利を盗むことはしないと答えたと伝えられています。戦場で敵の陣列にすきまが生まれた瞬間、王は騎兵とともにそこへ飛びこみ、ダレイオスはまたも逃げ去りました。',
      { routes: [{ name: '進軍', color: '#b8860b', pts: [[31.25, 29.85], [35.5, 33.0], [38.0, 36.8], [43.4, 36.6]] }],
        marks: [{ name: 'バビロン', lon: 44.42, lat: 32.54 }] }),
    S(-330, 'ペルセポリスの炎', 'ペルセポリス', 52.89, 29.94, 8, ['alexander'], ['alexander', 'achaemenid'],
      'ペルシアの都ペルセポリスに入り、宮殿は炎に包まれた。かつてペルシア軍がアテネを焼いた報復とも、宴の勢いともいわれる。逃げたダレイオスは部下に殺され、アケメネス朝は滅んだ。王はペルシア風の衣装や儀礼をとり入れ始めた。',
      '紀元前330年、王はペルシアの都ペルセポリスに入ります。やがて壮大な宮殿が炎に包まれました。150年前にペルシア軍がアテネを焼いたことへの報復とも、宴の席の勢いだったともいわれ、理由ははっきりしません。逃げていたダレイオスは、自分の部下に殺されました。王はペルシアの衣装や儀礼をとり入れ始めます。ギリシア人の部下たちは、これに強い不満を感じました。',
      { marks: [{ name: 'スサ', lon: 48.26, lat: 32.19 }, { name: 'エクバタナ', lon: 48.52, lat: 34.80 }] }),
    S(-328, '中央アジアの苦戦と悲劇', 'マラカンダ（サマルカンド）', 66.97, 39.65, 10, ['alexander'], ['alexander'],
      'ソグディアナの人びとのねばり強い抵抗に、遠征軍は2年以上苦しんだ。マラカンダの宴では、酒に酔った王が命の恩人クレイトスを槍で刺し殺し、深く後悔した。王はこの地の豪族の娘ロクサネと結婚した。',
      '中央アジアのソグディアナでは、山や砂漠を舞台にした抵抗が続き、遠征は2年以上も足止めされました。そしてマラカンダ、今のサマルカンドの宴で悲劇が起きます。王のペルシア化を批判した古い友人クレイトスを、酒に酔った王が槍で刺し殺してしまったのです。グラニコスで命を救ってくれた恩人でした。王は3日間部屋にこもって泣き続けたと伝えられています。',
      { routes: [{ name: '東方への進軍', color: '#b8860b', pts: [[52.89, 29.94], [54.4, 36.2], [62.2, 34.3], [66.9, 36.76], [66.97, 39.65]] }],
        marks: [{ name: 'バクトラ（バルフ）', lon: 66.9, lat: 36.76 }] }),
    S(-326, 'インダス川、兵士たちの拒否', 'ヒュダスペス河畔', 73.50, 32.90, 8, ['alexander'], ['alexander'],
      'インダス川をこえ、ヒュダスペス河畔の戦いでインドの王ポロスを破った。この地で愛馬ブケファラスが死んだ。さらに東へ進もうとしたが、ヒュパシス川で兵士たちが前進を拒み、王はついに引き返すことを決めた。',
      '紀元前326年、軍はインダス川をこえてインドに入りました。ヒュダスペス川の戦いではゾウの部隊をもつ王ポロスを破り、堂々とした態度のポロスを許して王の地位を認めます。この地で、少年時代からの愛馬ブケファラスが死にました。さらに東へ向かうと、故郷を離れて8年の兵士たちがついに前進を拒みます。王は3日間説得しましたが、最後は引き返すことを決めました。',
      { routes: [{ name: 'インドへの進軍', color: '#b8860b', pts: [[66.97, 39.65], [69.17, 34.53], [72.83, 33.74], [73.5, 32.9], [75.0, 31.6]] }],
        marks: [{ name: 'ヒュパシス川（引き返した地点）', lon: 75.0, lat: 31.6 }, { name: 'タキシラ', lon: 72.83, lat: 33.74 }] }),
    S(-324, 'スサの集団結婚式', 'スサ', 48.26, 32.19, 14, ['alexander'], ['alexander'],
      '帰り道のゲドロシア砂漠では、暑さと渇きで多くの兵を失った。スサにもどった王は、自分と部下の将兵がペルシア人の女性と結婚する集団結婚式を開き、マケドニア人とペルシア人の融合をめざした。',
      '帰り道、王はあえてゲドロシアの砂漠を通り、暑さと渇きで多くの兵を失いました。わずかな水を差し出された王は、兵が飲めないなら自分も飲まないと、地面に流したと伝えられています。スサにもどると、王は自分と部下の将兵が、ペルシア人の女性と結婚する集団結婚式を開きました。征服した側とされた側を一つにまとめる。それが王の新しい夢でした。',
      { routes: [{ name: 'ゲドロシア砂漠をこえる帰還', color: '#b8860b', pts: [[68.0, 25.5], [63.0, 26.0], [58.5, 27.2], [52.89, 29.94], [48.26, 32.19]] }] }),
    S(-323, 'バビロンでの死', 'バビロン', 44.42, 32.54, 6, ['alexander'], ['alexander'],
      'アラビア遠征を準備していたバビロンで熱病にかかり、32歳で亡くなった。後継者をたずねられ「最も強い者に」と答えたと伝えられる。帝国は将軍たちに分割されたが、彼が開いた東西の交流からヘレニズム文化が生まれた。',
      '紀元前323年、王はバビロンで次のアラビア遠征を準備していました。ところが宴のあと熱病にかかり、10日ほどで亡くなります。まだ32歳でした。だれに帝国をゆずるのかと聞かれ、最も強い者にと答えたと伝えられています。その言葉どおり、将軍たちの争いで帝国は分裂しました。それでも各地のアレクサンドリアを通じて、ギリシアとオリエントの文化がまじりあうヘレニズムの時代が始まったのです。',
      { marks: [{ name: 'アレクサンドリア（大王の墓が置かれた）', lon: 29.92, lat: 31.2 }] })
  ]
},
// ---------- ハンニバル ----------
{
  id: 'life-hannibal', kind: 'person', person: 'hannibal', title: 'ハンニバルの生涯', period: '前247〜前183年',
  region: 'africa', view: 'med', tags: ['tankyu'],
  summary: 'カルタゴの将軍ハンニバルは、ゾウを連れてアルプスをこえ、ローマを滅亡寸前まで追いこんだ。少年の日の誓いから、カンネーの大勝、ザマの敗北、亡命と死まで、ローマと戦いつづけた一生を地図でたどる。',
  steps: [
    S(-237, '9歳の誓い', 'カルタゴ', 10.32, 36.85, 4, ['hannibal'], ['carthage'],
      '第1回ポエニ戦争でローマに敗れたカルタゴ。将軍ハミルカルがイベリア半島へ向かうとき、9歳の息子ハンニバルは同行を願った。父は祭壇の前で、生涯ローマの味方にならないと誓わせたと伝えられる。',
      '物語は紀元前237年、北アフリカの港町カルタゴから始まります。カルタゴはローマとの戦争に敗れ、シチリア島を失ったばかりでした。将軍ハミルカルが新天地イベリア半島へ出発するとき、9歳の息子ハンニバルは連れて行ってほしいとせがみます。父は息子を祭壇の前に立たせ、生涯ローマの味方にならないと誓わせたと伝えられています。',
      { routes: [{ name: 'イベリア半島へ', color: '#7a3e9d', pts: [[10.32, 36.85], [5.0, 36.6], [-0.99, 37.6]] }] }),
    S(-221, '26歳の総司令官', 'カルタゴ=ノヴァ', -0.99, 37.60, 6, ['hannibal'], ['carthage'],
      '父の戦死、義兄ハスドルバルの暗殺をへて、26歳のハンニバルはイベリア半島のカルタゴ軍の総司令官に選ばれた。兵士と同じものを食べ、同じマントにくるまって地面で眠る指揮官として、兵の心をつかんだと伝えられる。',
      'イベリア半島で育ったハンニバルは、父を戦いで失い、あとをついだ義兄も暗殺されます。紀元前221年、兵士たちは26歳のハンニバルを総司令官に選びました。古代の歴史家によれば、彼は兵士と同じ食事をとり、マント一枚にくるまって見張りの兵のそばの地面で眠ったといいます。命令するだけでなく、ともに苦しむ指揮官だったのです。',
      { marks: [{ name: 'サグントゥム', lon: -0.27, lat: 39.68 }] }),
    S(-218, 'ゾウとともにアルプスをこえる', 'アルプス山脈', 6.90, 45.20, 14, ['hannibal'], ['carthage', 'rome-republic'],
      'ローマの同盟市サグントゥムの攻略から第2回ポエニ戦争が始まった。ハンニバルは海からではなく陸路を選び、ピレネー山脈、ローヌ川、そして雪のアルプスをこえてイタリアに入った。多くの兵とゾウを失う苦しい行軍だった。',
      'ローマは、カルタゴが海から来ると考えていました。ところがハンニバルは、だれも予想しない陸の道を選びます。ピレネー山脈をこえ、ローヌ川をいかだでゾウをわたし、秋の終わりに雪のアルプスに入りました。がけ道で兵や馬が次々と谷に落ち、イタリアの平野に下りたとき、兵は半分近くに減っていたといわれます。それでも北からの奇襲は、ローマを大混乱におとしいれました。',
      { routes: [{ name: 'ハンニバルの進軍', color: '#7a3e9d', pts: [[-0.99, 37.6], [0.5, 40.8], [2.8, 42.5], [4.6, 43.9], [5.9, 45.0], [6.9, 45.2], [7.68, 45.07], [9.6, 45.05]] }],
        marks: [{ name: 'トレビア川の戦い', lon: 9.6, lat: 45.05 }] }),
    S(-217, '片目を失う', 'トラシメヌス湖', 12.10, 43.15, 5, ['hannibal'], ['carthage', 'rome-republic'],
      'アルノ川流域の湿地を4日間進むあいだに、ハンニバルは目の病気にかかり片目の視力を失った。それでも霧のトラシメヌス湖畔でローマ軍を待ちぶせし、執政官もろとも全滅させた。',
      '紀元前217年の春、ハンニバルは近道として、増水したアルノ川の湿地帯を進みます。4日間も眠れぬまま水の中を歩くうち、彼は目の病気にかかり、片目の光を失いました。それでも、その数週間後、霧の立ちこめるトラシメヌス湖のほとりでローマ軍を待ちぶせし、執政官ごと打ち破ります。ローマでは、敗北を告げる知らせに市民が広場に集まり、大混乱になったといいます。',
      { marks: [{ name: 'アルノ川の湿地', lon: 10.8, lat: 43.75 }] }),
    S(-216, 'カンネーの包囲殲滅', 'カンネー', 16.13, 41.31, 4, ['hannibal'], ['carthage', 'rome-republic'],
      'ローマはかつてない大軍を送ったが、ハンニバルは中央をわざと後退させて敵を引きこみ、両翼と騎兵で包囲した。ローマ軍は数万人の戦死者を出した。部下に今すぐローマへ進めとうながされたが、彼は進まなかった。',
      '紀元前216年8月、イタリア南部のカンネーです。ローマ軍は8万をこえる大軍でした。ハンニバルは中央の部隊をわざと後ろに下げ、ローマ兵を奥へ引きこみます。そして左右の部隊と騎兵で、袋の口を閉じるように取り囲みました。今も士官学校で研究される包囲戦です。騎兵隊長のマハルバルは、あなたは勝ち方を知っているが勝利の使い方を知らないと嘆いたと伝えられています。',
      { marks: [{ name: 'ローマ', lon: 12.5, lat: 41.9 }] }),
    S(-211, 'ハンニバルが門前に', 'ローマ近郊', 12.50, 41.90, 4, ['hannibal'], ['carthage', 'rome-republic'],
      'ローマは決戦をさけ、同盟都市の多くも離反しなかった。包囲された同盟市カプアを救うため、ハンニバルはローマの城壁の近くまで迫ったが、攻め落とすことはできず、カプアはローマに奪い返された。',
      'カンネーの大勝のあとも、ローマは降伏しませんでした。正面からの決戦をさけ、ハンニバルの軍をじわじわと消耗させたのです。紀元前211年、彼はローマの城壁が見える所まで軍を進めました。ハンニバルが門前にいる。この言葉は、のちのちまでローマ人の恐怖の記憶となります。しかし城壁は固く、兵器も足りません。彼は引き返すしかありませんでした。',
      { routes: [{ name: 'ローマへの進軍', color: '#7a3e9d', pts: [[14.25, 41.08], [13.6, 41.6], [12.6, 41.95]] }],
        marks: [{ name: 'カプア', lon: 14.25, lat: 41.08 }] }),
    S(-207, '弟の首', 'ブルッティウム（イタリア南部）', 16.50, 39.30, 8, ['hannibal'], ['carthage', 'rome-republic'],
      '援軍を率いてアルプスをこえてきた弟ハスドルバルは、メタウルス川でローマ軍に敗れて戦死した。その首がハンニバルの陣に投げこまれたと伝えられる。彼は南イタリアの一角に追いつめられていった。',
      '紀元前207年、待ちに待った援軍が来ます。率いていたのは弟のハスドルバルで、兄と同じようにアルプスをこえてきました。ところが合流する前に、メタウルス川でローマ軍に討たれます。古代の歴史家リウィウスによれば、ローマ兵は弟の首をハンニバルの陣に投げこみました。それを見た彼は、カルタゴの運命を悟ったと伝えられています。',
      { marks: [{ name: 'メタウルス川の戦い', lon: 12.98, lat: 43.80 }] }),
    S(-202, 'ザマの戦い', 'ザマ', 9.45, 36.30, 6, ['hannibal'], ['carthage', 'rome-republic'],
      'ローマの若き将軍スキピオがカルタゴ本国を攻めたため、ハンニバルは15年ぶりに帰国した。ザマの戦いでは、スキピオがハンニバルの戦術を研究しつくしており、カルタゴ軍は敗れた。',
      'ローマの若き将軍スキピオは、ハンニバルのまねをしました。敵の本拠地をつくのです。カルタゴ本国が攻められ、ハンニバルは15年ぶりに故郷へ呼びもどされました。紀元前202年、ザマの戦いです。スキピオはゾウが通り抜けられるよう隊列にすきまをあけ、騎兵でハンニバル軍の背後をつきました。かつてカンネーで使われた戦い方で、ハンニバル自身が敗れたのです。',
      { routes: [{ name: '本国への帰還', color: '#7a3e9d', pts: [[16.9, 39.1], [13.5, 37.6], [10.32, 36.85]] }],
        marks: [{ name: 'カルタゴ', lon: 10.32, lat: 36.85 }] }),
    S(-196, '政治家として', 'カルタゴ', 10.32, 36.85, 3, ['hannibal'], ['carthage'],
      '戦後、ハンニバルはカルタゴの最高官職について、不正な役人を追及し、財政を立て直した。ローマへの賠償金も無理なく払える体制をつくったが、反発した有力者がローマに密告し、彼は国外に逃れた。',
      '敗戦のあと、ハンニバルは剣を置き、政治家として祖国の立て直しに取り組みます。最高の役職について役人の不正を追及し、税の仕組みを整え、ローマへの重い賠償金を払える財政をつくりました。しかし、利権を失った有力者たちは、彼がローマへの反乱をたくらんでいると密告します。紀元前195年、彼は夜の闇にまぎれて祖国を離れました。二度と帰ることはありませんでした。',
      {}),
    S(-195, 'シリア王のもとへ', 'アンティオキア', 36.16, 36.20, 8, ['hannibal'], ['seleucid', 'rome-republic'],
      '亡命したハンニバルは、セレウコス朝のアンティオコス3世に迎えられ、ローマとの戦いに助言した。しかし王は彼の意見をあまり用いず、セレウコス朝もローマに敗れて、ハンニバルの引き渡しが講和の条件とされた。',
      'ハンニバルが向かったのは、東地中海の大国セレウコス朝の都アンティオキアでした。ローマと対立していた王アンティオコス3世は、伝説の名将を迎えます。しかし王は、ハンニバルの大胆な作戦をあまり採用しませんでした。結局セレウコス朝もローマに敗れ、講和の条件の一つが、ハンニバルを引き渡すことだったのです。彼はふたたび逃げなければなりませんでした。',
      { routes: [{ name: '亡命の道', color: '#7a3e9d', pts: [[10.32, 36.85], [14.5, 35.5], [24.0, 35.3], [32.0, 35.8], [36.16, 36.2]] }] }),
    S(-183, '最後まで約束を守る', 'リビュッサ（ビテュニア）', 29.43, 40.80, 6, ['hannibal'], ['rome-republic'],
      '小アジアのビテュニア王国に身を寄せたが、ローマの使者が引き渡しを求めると、ハンニバルはいつも持っていた毒を飲んで命を絶った。60代半ばだった。カルタゴはその37年後、第3回ポエニ戦争で滅ぼされた。',
      '最後の亡命先は、小アジアのビテュニア王国でした。紀元前183年、ローマの使者が来て、王は彼の屋敷を兵で囲みます。逃げ道がないと知ったハンニバルは、いつも身につけていた毒を飲みました。ローマ人を長い心配から解放してやろう、と言い残したと伝えられています。9歳の日の誓いは、最後まで守られたのです。祖国カルタゴも、37年後にローマに滅ぼされました。',
      {})
  ]
},
// ---------- カエサル ----------
{
  id: 'life-caesar', kind: 'person', person: 'caesar', title: 'カエサルの生涯', period: '前100〜前44年',
  region: 'europe', view: 'med', tags: ['tankyu'],
  summary: '借金まみれの若い貴族から、ガリアの征服者、そしてローマの終身独裁官へ。カエサルの自信と人を引きつける力、大胆な決断の数々、そして暗殺までをたどり、共和政ローマが帝政へ向かう転換点を一人の人生から見る。',
  steps: [
    S(-100, 'ローマの下町の名門', 'ローマ', 12.50, 41.90, 2, ['caesar'], ['rome-republic'],
      'カエサルは、女神ウェヌスの子孫を名のる古い貴族ユリウス家に生まれたが、家は豊かではなく、下町スブラで育った。おばは民衆派の将軍マリウスの妻で、この縁から彼は民衆派の側に立つことになる。',
      '物語は紀元前100年のローマ、下町スブラから始まります。カエサルの家ユリウス家は、女神ウェヌスの子孫を名のる古い貴族でした。ところが家計は苦しく、まわりは職人や商人がひしめく庶民の町です。おばは民衆の英雄、将軍マリウスの妻でした。この縁から、若いカエサルは元老院の有力者ではなく、民衆の側に立って出世をめざすことになります。',
      { marks: [{ name: 'フォルム（広場）', lon: 12.485, lat: 41.892 }] }),
    S(-75, '海賊にとらえられる', 'ファルマクサ島', 27.00, 37.35, 6, ['caesar'], ['rome-republic'],
      '弁論を学ぶためロドス島へ向かう途中、海賊にとらえられた。身代金が20タラントンと聞くと、自分はもっと高いと50に上げさせ、解放後に艦隊を集めて海賊をとらえ、処刑したと伝えられる。',
      '25歳のころ、カエサルは弁論術を学ぶためにロドス島へ向かいました。その途中、エーゲ海で海賊にとらえられます。身代金は20タラントンと聞くと、カエサルは自分の値打ちはもっと高いと笑い、50タラントンに上げさせたと伝えられています。38日間、海賊と冗談をかわしながら、必ずお前たちを処刑すると予告しました。解放されると本当に船を集め、海賊をとらえてしまいます。',
      { marks: [{ name: 'ロドス島', lon: 28.22, lat: 36.44 }] }),
    S(-69, 'アレクサンドロス像の前の涙', 'ガデス', -6.29, 36.53, 6, ['caesar'], ['rome-republic'],
      '財務官としてヒスパニアに赴任したカエサルは、ガデスの神殿でアレクサンドロス大王の像を見て泣いたと伝えられる。大王が世界を征服した年齢になっても、自分は何もしていないと嘆いたという。',
      '30歳を過ぎたカエサルは、財務官として今のスペインにあたるヒスパニアに赴任しました。大西洋岸の町ガデスの神殿で、彼はアレクサンドロス大王の像の前に立ちます。そして涙を流したと伝えられています。大王はこの年でもう世界を征服していたのに、自分はまだ何も成しとげていない。そう嘆いたというのです。この焦りが、その後の猛烈な前進のばねになりました。',
      {}),
    S(-60, '三頭政治と執政官', 'ローマ', 12.50, 41.90, 2, ['caesar'], ['rome-republic'],
      '巨額の借金をしてまで見世物を開き、民衆の人気を集めたカエサルは、前60年、将軍ポンペイウス、富豪クラッススと第1回三頭政治を結んだ。翌年執政官となり、元老院の反対をおしきって法案を通した。',
      'カエサルは、剣闘士の試合などの見世物を気前よく開き、民衆の人気を集めました。その費用はほとんど借金です。紀元前60年、彼は二人の大物と手を組みます。東方を平定した将軍ポンペイウスと、ローマ一の大富豪クラッススです。これが第1回三頭政治です。さらに娘のユリアをポンペイウスと結婚させ、きずなを固めました。翌年、カエサルは執政官となります。',
      {}),
    S(-58, 'ガリア遠征へ', 'ビブラクテ', 4.03, 46.92, 10, ['caesar'], ['rome-republic'],
      '属州総督となったカエサルは、ガリア（今のフランス）に移動しようとしたヘルウェティイ族を破り、ガリア全体の征服に乗りだした。ライン川に橋をかけ、ブリタニアにも上陸した。この記録が『ガリア戦記』である。',
      '紀元前58年、総督となったカエサルは、アルプスの北のガリアへ向かいます。今のフランスやベルギーにあたる広い土地です。彼はわずか10日でライン川に木の橋をかけ、海をわたってブリタニアにも上陸しました。その様子は、本人が書いたガリア戦記にくわしく残っています。自分のことをカエサルはと三人称で書く、冷静で簡潔な文章です。',
      { routes: [{ name: 'カエサルの遠征', color: '#a3242a', pts: [[6.15, 46.2], [4.03, 46.92], [4.8, 49.0], [7.2, 50.6]] }, { name: 'ブリタニアへ', color: '#a3242a', pts: [[1.6, 50.9], [1.3, 51.2]] }],
        marks: [{ name: 'ライン川の架橋', lon: 7.2, lat: 50.6 }] }),
    S(-52, 'アレシアの包囲', 'アレシア', 4.50, 47.54, 5, ['caesar'], ['rome-republic'],
      'ガリア諸部族はウェルキンゲトリクスのもとで一斉に反乱した。カエサルはアレシアの町を二重の壁で囲み、内からの攻撃と外からの救援軍を同時に退けた。ウェルキンゲトリクスは降伏し、ガリア征服はほぼ完成した。',
      '紀元前52年、ガリアの部族は若き指導者ウェルキンゲトリクスのもとで団結し、反乱を起こしました。カエサルは彼がこもったアレシアの町を囲み、壁を二重に築きます。内側の壁は町の敵に、外側の壁はかけつける救援軍にそなえたものでした。前後からの攻撃を受けながら、ローマ軍は持ちこたえます。ウェルキンゲトリクスは自ら武器を置き、カエサルの前に降伏しました。',
      { lines: [{ name: '包囲の壁', pts: [[4.47, 47.52], [4.52, 47.51], [4.55, 47.55], [4.5, 47.58], [4.46, 47.56], [4.47, 47.52]] }] }),
    S(-49, 'ルビコン川をわたる', 'ルビコン川', 12.38, 44.10, 4, ['caesar'], ['rome-republic'],
      '元老院はカエサルに軍を解散してローマに戻るよう命じた。軍を率いて本国との境界ルビコン川をこえれば国家への反逆になる。前49年1月、カエサルは「賽は投げられた」と言って川をわたったと伝えられる。',
      'カエサルの力をおそれた元老院は、ポンペイウスと手を組み、軍を手放して一人で帰れと命じました。丸腰で帰れば、裁判にかけられて政治生命は終わります。軍を連れて境界のルビコン川をわたれば、国家への反逆です。紀元前49年1月、カエサルは川の前でしばらく迷い、賽は投げられたと言ってわたったと伝えられています。内戦の始まりでした。',
      { routes: [{ name: 'ローマへの進軍', color: '#a3242a', pts: [[12.2, 44.4], [12.38, 44.1], [12.57, 44.06], [13.5, 43.6], [12.5, 41.9]] }],
        marks: [{ name: 'ラヴェンナ', lon: 12.2, lat: 44.42 }, { name: 'アリミヌム', lon: 12.57, lat: 44.06 }] }),
    S(-48, 'クレオパトラとの出会い', 'アレクサンドリア', 29.92, 31.20, 6, ['caesar', 'cleopatra'], ['rome-republic', 'ptolemaic'],
      'ファルサロスの戦いでポンペイウスを破り、逃げた彼を追ってエジプトへ行くと、ポンペイウスはすでに殺されていた。カエサルはその首を見て涙したという。ここで王位を争う女王クレオパトラと出会い、彼女を支えた。',
      'ギリシアのファルサロスでポンペイウスを破ったカエサルは、逃げた彼を追ってエジプトのアレクサンドリアに着きます。差し出されたのは、かつての盟友で娘婿だったポンペイウスの首でした。カエサルは顔をそむけて泣いたといわれます。ここで彼は、弟と王位を争う21歳の女王クレオパトラと出会います。彼女は寝具の袋に身を隠して、カエサルのもとに運ばせたと伝えられています。',
      { routes: [{ name: 'ポンペイウスを追う', color: '#a3242a', pts: [[22.38, 39.3], [26.0, 36.5], [29.92, 31.2]] }],
        marks: [{ name: 'ファルサロス', lon: 22.38, lat: 39.3 }] }),
    S(-47, '来た、見た、勝った', 'ゼラ', 35.90, 40.30, 6, ['caesar'], ['rome-republic'],
      '小アジアで反乱を起こしたポントス王ファルナケスを、カエサルはゼラの戦いでわずか数時間で破った。ローマへの報告は「来た、見た、勝った」の3語だけだったと伝えられる。',
      '紀元前47年、小アジアの黒海沿岸の王ファルナケスが、内戦のすきをついて領土を広げました。カエサルはエジプトから急行し、ゼラの戦いでわずか数時間のうちに勝利します。ローマの友人への報告は、ラテン語でたった3語でした。来た、見た、勝った。短く、速く、自信に満ちた言葉は、カエサルという人をよくあらわしています。',
      { routes: [{ name: '急行', color: '#a3242a', pts: [[29.92, 31.2], [35.5, 33.5], [36.16, 36.2], [35.9, 40.3]] }] }),
    S(-44, '3月15日', 'ポンペイウス劇場（ローマ）', 12.475, 41.895, 0.5, ['caesar', 'augustus'], ['rome-republic'],
      '終身独裁官となったカエサルは、ユリウス暦の採用などの改革を進めたが、王になろうとしていると警戒された。前44年3月15日、元老院の会議場で、目をかけていたブルートゥスらに刺され、亡くなった。',
      'ローマにもどったカエサルは、太陽の動きにもとづくユリウス暦を定めるなど、次々と改革を進めます。英語の7月、ジュライは、彼の家名ユリウスに由来します。しかし終身独裁官となった彼に、共和政を守ろうとする議員たちは危機を感じました。紀元前44年3月15日、ポンペイウス劇場の会議場で、彼は23か所を刺されて倒れます。あとをついだのは、18歳の養子オクタウィアヌスでした。',
      { marks: [{ name: 'フォルム', lon: 12.485, lat: 41.892 }],
        lines: [{ name: 'ティベル川', pts: [[12.466, 41.91], [12.47, 41.9], [12.476, 41.89], [12.48, 41.885]] }] })
  ]
},
// ---------- 始皇帝 ----------
{
  id: 'life-shi-huangdi', kind: 'person', person: 'shi-huangdi', title: '始皇帝の生涯', period: '前259〜前210年',
  region: 'east', view: 'china', tags: ['tankyu'],
  summary: '人質の子として敵国に生まれた政は、13歳で秦王となり、39歳で中国を統一して「皇帝」を名のった。命をねらわれ、不老不死を求め、巡行の旅先で死んだ始皇帝の一生を、生まれた邯鄲から最期の沙丘までたどる。',
  steps: [
    S(-259, '人質の子', '邯鄲', 114.49, 36.61, 5, ['shi-huangdi'], ['zhao-state', 'qin-state'],
      '政（のちの始皇帝）は、趙の都邯鄲で、秦から人質として送られていた王族の子として生まれた。父を支えたのは大商人の呂不韋だった。秦と趙は激しく争っており、幼い政は敵国で命の危険とともに育った。',
      '物語は紀元前259年、趙の国の都、邯鄲から始まります。のちの始皇帝、政が生まれたのは、敵国の都でした。父は秦から人質として送られてきた王族で、その父に大金をつぎこんで後押ししたのが大商人の呂不韋です。この年の前後、秦は趙の兵を大量に殺す戦いをしていました。秦の子である幼い政は、まわりの憎しみの中で、息をひそめて育ったのです。',
      { marks: [{ name: '咸陽（秦の都）', lon: 108.71, lat: 34.33 }] }),
    S(-247, '13歳の秦王', '咸陽', 108.71, 34.33, 4, ['shi-huangdi'], ['qin-state'],
      '父が秦王となったのちに死去し、13歳の政が即位した。政治は宰相となった呂不韋がとりしきり、若い王はその陰で成長した。呂不韋が政の本当の父だという話もあるが、確かではない。',
      '父はやがて秦の王になりましたが、わずか3年で亡くなります。紀元前247年、13歳の政が王位につきました。政治の実権をにぎったのは、宰相となった呂不韋です。後の時代には、呂不韋こそ政の本当の父だといううわさも語られましたが、確かな証拠はありません。少年王は、大人たちの思惑のなかで、じっと力をたくわえていきました。',
      { routes: [{ name: '邯鄲から秦へ', color: '#333333', pts: [[114.49, 36.61], [112.45, 34.62], [110.3, 34.5], [108.71, 34.33]] }] }),
    S(-237, '親政の始まり', '雍', 107.40, 34.50, 4, ['shi-huangdi'], ['qin-state'],
      '22歳で成人の儀式を行った政は、反乱をしずめ、呂不韋を退けて自ら政治を行い始めた。他国出身者を追放する命令が出たとき、李斯の意見書を読んで命令を取り消し、能力のある人材を国の外からも集めた。',
      '紀元前238年、22歳の政は、古い都の雍で成人の儀式を行います。その最中に反乱が起きますが、王はすばやくこれをしずめ、翌年には呂不韋も退けました。このころ、他国から来た者をすべて追い出せという意見が出ます。これに反対したのが楚の出身の李斯でした。泰山は小さな土くれも拒まないから高いのです。この意見書を読んだ政は命令を取り消し、出身を問わず人材を集めました。',
      { marks: [{ name: '咸陽', lon: 108.71, lat: 34.33 }] }),
    S(-227, '刺客荊軻', '咸陽宮', 108.71, 34.33, 2, ['shi-huangdi'], ['qin-state', 'yan-state'],
      '燕の太子丹が送った刺客荊軻は、献上する地図の巻物の中に短剣をかくし、王に迫った。政は柱のまわりを逃げまわり、ようやく剣を抜いて荊軻を倒した。以後、王の警戒心はいっそう強くなった。',
      '紀元前227年、咸陽の宮殿に燕の国の使者がやってきました。燕の土地の地図をさしあげます、と巻物を広げていくと、最後に短剣があらわれます。使者は刺客の荊軻でした。王は袖をつかまれ、柱のまわりを必死に逃げます。家臣は武器を持って王の近くに上がることを禁じられていたため、だれも助けられません。王はようやく背中の長い剣を抜き、荊軻を切り倒しました。',
      { marks: [{ name: '燕の都・薊', lon: 116.4, lat: 39.9 }] }),
    S(-221, '中国統一と「皇帝」', '咸陽', 108.71, 34.33, 16, ['shi-huangdi'], ['qin'],
      '前230年の韓から前221年の斉まで、秦は10年で六国を滅ぼした。39歳の政は、王をこえる称号として「皇帝」を名のり、自らを始皇帝とした。郡県制をしき、文字・度量衡・貨幣を統一した。',
      '紀元前230年に韓、続いて趙、魏、楚、燕、そして紀元前221年に斉。秦はわずか10年で、ほかの六つの国をすべて滅ぼしました。39歳の政は、王という呼び名では足りないと考え、伝説の聖人たちの呼び名から皇帝という称号をつくります。自分は最初の皇帝だから始皇帝。子孫は二世、三世と、万世まで続くはずでした。文字や単位、お金もそろえられ、中国は一つの国になりました。',
      { marks: [{ name: '韓（前230年）', lon: 113.6, lat: 34.4 }, { name: '趙（前228年）', lon: 114.49, lat: 36.61 }, { name: '魏（前225年）', lon: 114.35, lat: 34.79 }, { name: '楚（前223年）', lon: 116.8, lat: 32.6 }, { name: '燕（前222年）', lon: 116.4, lat: 39.9 }, { name: '斉（前221年）', lon: 118.35, lat: 36.85 }] }),
    S(-219, '泰山と東の海', '泰山', 117.10, 36.25, 8, ['shi-huangdi'], ['qin'],
      '始皇帝は全国を巡行し、泰山で天と地をまつる儀式（封禅）を行った。東の海辺の琅邪では、方士徐福の願いを聞き入れ、不老不死の薬を求めて若い男女数千人を海へ送り出したと伝えられる。',
      '統一の2年後、始皇帝は東方の巡行に出ます。聖なる山、泰山に登り、天と地に統一を報告する儀式を行いました。さらに東の海辺の琅邪に着くと、方士の徐福が、海の向こうの神の山に仙人がいると申し出ます。始皇帝は、若い男女数千人を乗せた船を出させたと伝えられています。徐福は戻らず、日本に来たという伝説も各地に残っていますが、確かではありません。',
      { routes: [{ name: '東方巡行', color: '#333333', pts: [[108.71, 34.33], [112.45, 34.62], [116.99, 35.58], [117.1, 36.25], [119.9, 35.6]] }],
        marks: [{ name: '琅邪', lon: 119.9, lat: 35.6 }] }),
    S(-215, '北の長城', 'オルドス（河南の地）', 109.50, 39.50, 12, ['shi-huangdi'], ['qin'],
      '「秦を滅ぼすのは胡である」という予言の書を見た始皇帝は、将軍蒙恬に30万の兵を与えて北方の遊牧民を討たせ、戦国時代の長城をつなぎ直させた。南では嶺南（今の広東）にも軍を送った。',
      '巡行の旅で、始皇帝はある予言の書を手に入れました。秦を滅ぼす者は胡である。胡とは北方の遊牧民のことだと考えた始皇帝は、将軍蒙恬に30万の兵を与えて北へ送ります。黄河の大きな曲がり目のオルドスを奪い、戦国時代の各国の長城をつなぎ合わせました。のちの人びとは、胡とは遊牧民ではなく、末っ子の胡亥のことだったと語りました。',
      { lines: [{ name: '秦の長城', pts: [[103.8, 36.1], [106.5, 38.0], [109.0, 40.6], [112.5, 41.0], [116.0, 41.5], [120.0, 42.0], [123.5, 41.0]] }] }),
    S(-212, '焚書坑儒と巨大工事', '驪山', 109.25, 34.38, 2, ['shi-huangdi'], ['qin'],
      '政治を批判する学者をおさえるため実用書以外の書物を焼かせ、儒者らを生き埋めにしたと伝えられる。巨大な宮殿阿房宮や驪山の陵墓の工事に、何十万もの人がかり出され、不満が高まっていった。',
      '紀元前213年、李斯の進言で、医学や農業などの実用書を除く書物が焼かれました。翌年には、始皇帝を批判した学者たち460人あまりを生き埋めにしたと伝えられています。そのころ咸陽の近くでは、巨大な宮殿阿房宮と、驪山の陵墓の工事が進んでいました。陵墓のそばには、のちに兵馬俑とよばれる、顔がひとつひとつちがう土の兵士の大軍が並べられました。',
      { marks: [{ name: '咸陽', lon: 108.71, lat: 34.33 }, { name: '兵馬俑坑', lon: 109.28, lat: 34.385 }, { name: '阿房宮', lon: 108.84, lat: 34.27 }] }),
    S(-210, '巡行の果ての死', '沙丘', 115.10, 37.40, 10, ['shi-huangdi'], ['qin'],
      '5度目の巡行の途中、始皇帝は沙丘で病死した。50歳だった。宦官の趙高と李斯は死をかくし、遺言を書きかえて末子の胡亥を即位させた。翌年、陳勝・呉広の乱が起こり、秦は統一からわずか15年で滅んだ。',
      '紀元前210年、5度目の巡行に出た始皇帝は、旅の途中の沙丘で倒れます。50歳でした。この巡行を見物した若者の中に、のちに秦を倒す項羽がいて、あれに取って代わってやると言ったと伝えられています。死は隠され、遺体は車で都へ運ばれました。宦官の趙高と李斯は遺言を書きかえ、末っ子の胡亥を皇帝にします。翌年には反乱が起こり、秦はわずか15年で滅びました。',
      { routes: [{ name: '最後の巡行', color: '#333333', pts: [[108.71, 34.33], [112.0, 32.0], [118.78, 32.06], [120.58, 30.0], [119.9, 35.6], [115.1, 37.4], [111.0, 38.5], [108.71, 34.33]] }],
        marks: [{ name: '会稽', lon: 120.58, lat: 30.0 }] })
  ]
},
// ---------- 張騫 ----------
{
  id: 'life-zhang-qian', kind: 'person', person: 'zhang-qian', title: '張騫の生涯', period: '前139〜前114年ごろ',
  region: 'east', view: 'inner', tags: ['tankyu'],
  summary: '漢の武帝の命で匈奴をはさみうちにする同盟を求め、西へ旅立った張騫。とらわれの10年、失敗した交渉、13年ぶりの帰国、そして再び西域へ。彼の旅がシルクロードを開くきっかけとなった。',
  steps: [
    S(-139, '名乗り出た使者', '長安', 108.94, 34.26, 6, ['zhang-qian', 'wudi'], ['qianhan'],
      '匈奴の捕虜から、月氏が王を殺されて匈奴をうらんでいると聞いた武帝は、月氏と結ぶ使者を募った。応じたのが張騫だった。匈奴出身の従者甘父を案内役に、100人あまりの一行で長安を出発した。',
      '物語は紀元前139年ごろ、漢の都、長安から始まります。若い皇帝の武帝は、北方の匈奴に悩まされていました。ある日、捕虜の話から、西の月氏という民族が匈奴に王を殺され、うらんでいると知ります。月氏と手を組めば、匈奴をはさみうちにできる。だれも行ったことのない西の果てへの使者に名乗り出たのが、宮廷の役人、張騫でした。',
      { routes: [{ name: '出発', color: '#c0392b', pts: [[108.94, 34.26], [103.8, 36.1], [100.5, 38.9]] }] }),
    S(-138, 'とらわれの10年', '匈奴の地', 106.00, 44.00, 14, ['zhang-qian'], ['xiongnu', 'qianhan'],
      '河西回廊を進んだ一行は、すぐ匈奴にとらえられた。単于は張騫を殺さず、匈奴の妻を与えて10年ほど引きとめた。張騫は子どもまでもうけたが、漢の使者のしるしである節を手放さなかった。',
      '一行は、匈奴の勢力圏だった河西回廊で、すぐにとらえられてしまいます。匈奴の王である単于は、張騫を殺しませんでした。妻を与え、ここで暮らせと引きとめたのです。張騫は匈奴の地で10年ほどを過ごし、子どもも生まれました。それでも彼は、漢の使者のしるしである節という旗のついた杖を、決して手放さなかったと記録されています。',
      { marks: [{ name: '単于の本拠地', lon: 102.8, lat: 47.2 }] }),
    S(-129, '脱出、大宛へ', '大宛（フェルガナ）', 71.80, 40.60, 10, ['zhang-qian'], ['yuezhi'],
      '見張りがゆるんだすきに、張騫は従者とともに脱出し、西へ走った。たどりついた大宛（フェルガナ）は、汗血馬とよばれる名馬の産地だった。漢の豊かさを聞いていた大宛王は喜び、案内をつけて送り出した。',
      '10年がたち、見張りがゆるんだすきに、張騫は従者とともに逃げ出します。目的を忘れず、まっすぐ西へ向かいました。天山山脈をこえて着いたのは大宛、今のフェルガナ盆地です。ここは血のような汗を流して走るといわれた名馬、汗血馬の産地でした。漢の豊かさをうわさで知っていた大宛の王は喜び、案内と通訳をつけて先へ送り出してくれました。',
      { routes: [{ name: '脱出', color: '#c0392b', pts: [[106.0, 44.0], [95.0, 43.0], [87.5, 43.8], [80.0, 42.0], [75.99, 39.47], [71.8, 40.6]] }] }),
    S(-128, '断られた同盟', 'バクトリア（大夏）', 66.90, 36.76, 8, ['zhang-qian'], ['yuezhi'],
      'ようやく会えた大月氏は、豊かなアム川流域に移り住んで満足しており、匈奴への復讐の気持ちはなかった。張騫は1年あまり説得したが同盟はならなかった。しかし大夏の市場で四川の竹の杖と布を見つけた。',
      'ついに大月氏の地にたどりつきました。ところが月氏の人びとは、アム川流域の豊かな土地に移り住み、すっかり満足していました。遠い漢と組んで匈奴と戦う気など、もうなかったのです。1年あまり説得しても、答えは変わりませんでした。ただ、隣の大夏の市場で、張騫は思わぬものを見つけます。故郷に近い四川の竹の杖と布でした。インドを通って運ばれてきたというのです。',
      { routes: [{ name: '大月氏へ', color: '#c0392b', pts: [[71.8, 40.6], [69.0, 40.0], [66.97, 39.65], [66.9, 36.76]] }],
        marks: [{ name: 'アム川', lon: 66.5, lat: 37.5 }] }),
    S(-127, 'ふたたびとらわれる', '河西（祁連山のふもと）', 100.50, 38.90, 12, ['zhang-qian'], ['xiongnu'],
      '帰りは匈奴をさけ、崑崙山脈ぞいの南の道を選んだが、またも匈奴にとらえられた。1年あまり後、単于が死んで匈奴の内部が争いになったすきに、匈奴の妻と甘父を連れて脱出した。',
      '帰り道、張騫は匈奴の土地をさけようと、崑崙山脈にそった南の道を選びます。しかし、羌族の地を通ったところで、またも匈奴にとらえられてしまいました。1年あまりのち、単于が死に、匈奴の中で後継ぎ争いが起こります。その混乱をついて、張騫は匈奴の妻と、忠実な従者の甘父を連れて逃げ出しました。今度こそ、まっすぐ東へ向かいます。',
      { routes: [{ name: '帰り道', color: '#c0392b', pts: [[66.9, 36.76], [75.99, 39.47], [79.92, 37.11], [88.0, 38.0], [94.66, 40.14], [100.5, 38.9]] }] }),
    S(-126, '13年ぶりの帰国', '長安', 108.94, 34.26, 6, ['zhang-qian', 'wudi'], ['qianhan'],
      '出発から13年、100人あまりの一行のうち帰りついたのは張騫と甘父の2人だけだった。同盟は失敗したが、張騫は西域の国々の地理や産物、軍事力をくわしく武帝に報告し、太中大夫に任じられた。',
      '紀元前126年、張騫は長安に帰りつきました。出発から13年。100人あまりいた一行で、生きて帰れたのは張騫と甘父の二人だけでした。同盟という目的は果たせませんでした。しかし彼の頭の中には、だれも知らなかった西の世界の地図がありました。どこに水があり、どんな国があり、何が売られているか。武帝は目を輝かせて聞き入ったといいます。',
      {}),
    S(-123, '博望侯となる', '漠南（ゴビ砂漠の南）', 110.00, 41.50, 10, ['zhang-qian'], ['qianhan', 'xiongnu'],
      '大将軍衛青の匈奴遠征に加わった張騫は、砂漠の水や草のある場所を知っていたので、軍は飢えや渇きに苦しまなかった。この功績で博望侯の地位を与えられ、武帝の信頼はいっそう厚くなった。',
      '紀元前123年、張騫は大将軍衛青の遠征軍に加わり、匈奴を攻めました。砂漠で軍を苦しめるのは、敵よりも水と草の不足です。匈奴の地で10年を過ごした張騫は、どこに水があり、どこで馬を休ませられるかを知っていました。おかげで軍は無事に戦えたのです。この功績で、彼は博望侯という地位を与えられました。広く遠くを望む、という意味がこめられています。',
      { routes: [{ name: '衛青の遠征', color: '#c0392b', pts: [[108.94, 34.26], [112.55, 37.87], [111.0, 40.5], [110.0, 41.8]] }] }),
    S(-121, '遅刻の罪', '右北平', 118.90, 41.00, 8, ['zhang-qian'], ['qianhan', 'xiongnu'],
      '将軍李広とともに匈奴を攻めたが、張騫の部隊が約束の日に遅れ、李広の軍は大きな損害を受けた。張騫は死刑を言い渡され、財産を払って死をまぬかれたものの、庶民の身分に落とされた。',
      '順調に見えた張騫の人生に、つまずきが訪れます。紀元前121年、名将李広とともに東の右北平から匈奴を攻めたとき、張騫の部隊が待ち合わせの日に遅れてしまったのです。李広の軍は孤立して大きな損害を出しました。張騫は死刑を言い渡され、お金を払って命は助かりましたが、地位を失って庶民になりました。同じ年、霍去病が河西回廊を奪っています。',
      { marks: [{ name: '河西回廊（霍去病が奪う）', lon: 100.5, lat: 38.9 }] }),
    S(-119, 'ふたたび西へ', '烏孫（イリ地方）', 81.30, 43.90, 12, ['zhang-qian', 'wudi'], ['wusun', 'qianhan'],
      '張騫は烏孫と結ぶ策を武帝に説き、300人の一行と牛や羊、金や絹を携えて再び西へ向かった。烏孫は同盟に応じなかったが、張騫は副使たちを大宛・康居・大月氏・安息・身毒（インド）などへ送った。',
      'それでも武帝は張騫を見捨てませんでした。張騫は、天山のふもとの烏孫と手を結ぶ策を説きます。紀元前119年、彼は300人の一行と、数万頭の牛や羊、山のような金や絹を携え、ふたたび西へ向かいました。烏孫は漢との同盟をためらいましたが、張騫は副使たちを、大宛、大月氏、パルティアの安息、インドの身毒へと次々に送り出しました。',
      { routes: [{ name: '2度目の旅', color: '#c0392b', pts: [[108.94, 34.26], [100.5, 38.9], [94.66, 40.14], [89.19, 42.95], [81.3, 43.9]] }, { name: '副使の派遣', color: '#e67e22', pts: [[81.3, 43.9], [71.8, 40.6], [66.9, 36.76], [59.6, 36.3]] }] }),
    S(-115, '道をひらいた人', '長安', 108.94, 34.26, 30, ['zhang-qian', 'wudi'], ['qianhan'],
      '張騫は烏孫の使者と名馬を連れて帰国し、翌年ごろ亡くなった。その後、副使たちが各国の使者を連れて戻り、西域との往来が始まった。のちの使者たちは博望侯の名を出して信用を得たという。',
      '紀元前115年、張騫は烏孫の使者と数十頭の馬を連れて帰国し、翌年ごろに亡くなりました。その後、各地へ送った副使たちが、それぞれの国の使者を連れて長安に戻ってきます。漢と西方を結ぶ道が、ここから本格的に動き始めました。のちに西へ向かう使者たちは、博望侯の名を出して相手の信用を得たと記録されています。のちにシルクロードとよばれる道の、最初の一歩でした。',
      { routes: [{ name: 'のちのシルクロード', color: '#e67e22', pts: [[108.94, 34.26], [100.5, 38.9], [94.66, 40.14], [89.19, 42.95], [75.99, 39.47], [66.97, 39.65], [59.6, 36.3], [44.4, 33.3], [36.16, 36.2]] }] })
  ]
},
// ---------- 則天武后 ----------
{
  id: 'life-wu-zetian', kind: 'person', person: 'wu-zetian', title: '則天武后の生涯', period: '624〜705年',
  region: 'east', view: 'china', tags: ['tankyu'],
  summary: '太宗の後宮に入った14歳の少女は、尼寺をへて高宗の皇后となり、ついには中国史上ただ一人の女性皇帝となった。恐怖政治と人材登用、仏教保護。則天武后の一生を、長安と洛陽、そして朝鮮半島までの動きとともにたどる。',
  steps: [
    S(624, '材木商人の娘', '并州（太原）', 112.55, 37.87, 6, ['wu-zetian'], ['tang'],
      '則天武后（武照）は、并州出身の武士彠の娘として生まれた。父は材木商人から身をおこし、唐を建てた李淵の挙兵を助けて高官となった。名門の出ではない家柄は、のちのちまで彼女につきまとった。',
      '物語は624年、唐が建てられてまもないころから始まります。のちの則天武后、武照の父は、もとは材木を商う商人でした。唐を建てた李淵が今の太原で兵をあげたとき、資金を出して助け、高い位を与えられたのです。とはいえ、古い名門貴族から見れば成り上がりの家でした。この家柄の低さを、彼女は一生、はね返そうとし続けることになります。',
      { marks: [{ name: '長安', lon: 108.94, lat: 34.26 }] }),
    S(637, '太宗の後宮へ', '長安（太極宮）', 108.94, 34.26, 2, ['wu-zetian', 'taizong'], ['tang'],
      '14歳で太宗の後宮に入り、才人の位を与えられた。母は泣いて見送ったが、彼女は天子に会えるのは幸せなことだと言ったという。暴れ馬をならすには鉄のむち、かなづち、短剣があればよいと太宗に答えたと伝えられる。',
      '637年、14歳の武照は、名君として知られる太宗の後宮に入ります。泣いて別れを惜しむ母に、天子にお会いできるのが不幸なはずがありませんと言ったと伝えられています。後年、彼女自身が語った話があります。だれもならせない暴れ馬について、鉄のむちとかなづちと短剣があればならせます、と太宗に答えたというのです。しかし太宗のもとで、彼女が出世することはありませんでした。',
      { marks: [{ name: '大明宮（のちの宮殿）', lon: 108.96, lat: 34.29 }] }),
    S(649, '尼寺からの帰還', '感業寺（長安）', 108.90, 34.30, 2, ['wu-zetian'], ['tang'],
      '太宗が亡くなると、後宮の女性たちは尼寺に入れられた。武照も髪をおろしたが、太宗の病床で知り合った皇太子、のちの高宗が彼女を忘れず、尼寺を訪れて再会し、やがて宮中に呼びもどした。',
      '649年、太宗が亡くなります。しきたりにより、子のない後宮の女性たちは尼寺に入れられ、武照も髪をおろして感業寺の尼になりました。ふつうなら、ここで人生は終わりです。しかし、太宗の看病の場で彼女と知り合っていた皇太子、のちの高宗が彼女を忘れませんでした。高宗は寺を訪れて再会し、やがて彼女を宮中に呼びもどします。父の妃を息子が迎える、異例のことでした。',
      {}),
    S(655, '皇后の座へ', '長安（大明宮）', 108.96, 34.29, 2, ['wu-zetian'], ['tang'],
      '宮中にもどった武照は、高宗の寵愛を受け、王皇后と争った。重臣の長孫無忌らは強く反対したが、高宗は「これは陛下の家の事だ」という李勣の言葉に押され、655年、王皇后を廃して武照を皇后に立てた。',
      '宮中にもどった武照は、高宗の心をつかみ、皇后の王氏と激しく争います。皇后を替えることに、太宗以来の重臣、長孫無忌たちは強く反対しました。しかし、将軍の李勣は、これは陛下の家の事、ほかの者にたずねる必要はありませんと答えます。655年、32歳の武照は皇后となりました。反対した重臣たちは、その後次々と都を追われていきます。',
      {}),
    S(660, '病の皇帝にかわって', '洛陽', 112.45, 34.62, 22, ['wu-zetian'], ['tang', 'silla', 'baekje', 'goguryeo'],
      '高宗が目まいの持病に苦しむようになると、武后が政治の決裁を行うようになった。この時代、唐は新羅と結んで660年に百済、668年に高句麗を滅ぼし、領土は最大となった。',
      '660年ごろから、高宗は目まいの持病に苦しみ、書類を読むこともつらくなります。かわって決裁を行ったのが、文書に強い武后でした。同じ660年、唐は新羅と手を組んで朝鮮半島の百済を滅ぼし、668年には高句麗も滅ぼします。この時期、唐の勢力は最も広がりました。人びとは、玉座に並ぶ高宗と武后を、二人の聖人、二聖とよびました。',
      { routes: [{ name: '唐軍（百済へ）', color: '#c48a00', pts: [[120.6, 37.6], [123.5, 36.8], [126.5, 36.2], [126.91, 36.28]] }, { name: '唐軍（高句麗へ）', color: '#c48a00', pts: [[116.4, 39.9], [121.0, 41.0], [123.43, 41.8], [125.75, 39.03]] }],
        marks: [{ name: '百済の都・泗沘', lon: 126.91, lat: 36.28 }, { name: '高句麗の都・平壌', lon: 125.75, lat: 39.03 }, { name: '新羅の都・金城', lon: 129.21, lat: 35.84 }] }),
    S(675, '龍門の大仏', '龍門石窟', 112.47, 34.56, 0.8, ['wu-zetian'], ['tang'],
      '洛陽の南の龍門石窟に、高さ17メートルをこえる盧舎那仏が完成した。皇后は自分の化粧料から2万貫を寄付したと記録されている。仏の穏やかな顔は、武后をモデルにしたという伝説もある。',
      '洛陽の南、伊河の両岸に広がる龍門石窟に、675年、高さ17メートルをこえる大きな仏像が完成しました。盧舎那仏です。皇后は、自分の化粧のための費用から2万貫を寄付したと、石に刻まれています。仏の穏やかでふくよかな顔は武后をモデルにしたという話も伝わっていますが、確かな証拠はありません。仏教は、彼女の権力を支える柱になっていきます。',
      { lines: [{ name: '伊河', pts: [[112.46, 34.52], [112.47, 34.55], [112.475, 34.58], [112.49, 34.61]] }],
        marks: [{ name: '洛陽城', lon: 112.45, lat: 34.62 }] }),
    S(684, '息子たちを退けて', '揚州', 119.42, 32.39, 10, ['wu-zetian'], ['tang'],
      '683年に高宗が死去すると、武后は即位した中宗を2か月足らずで退け、弟の睿宗を立てて実権をにぎった。揚州で起きた反乱の檄文を読んだ武后は、こんな才能を用いなかったのは宰相の過ちだと言ったという。',
      '683年、高宗が亡くなります。即位した息子の中宗が、皇后の一族を重く用いようとすると、武后はわずか2か月足らずで退位させ、弟の睿宗を立てました。684年、南の揚州で反乱が起こります。詩人の駱賓王が書いた、武后を激しく非難する檄文を読んだ武后は、怒るどころか、これほどの人材を用いなかったのは宰相の過ちだと言ったと伝えられています。反乱は2か月ほどで鎮圧されました。',
      { routes: [{ name: '討伐軍', color: '#c48a00', pts: [[112.45, 34.62], [116.0, 33.5], [119.42, 32.39]] }],
        marks: [{ name: '洛陽', lon: 112.45, lat: 34.62 }] }),
    S(690, '女性皇帝の誕生', '洛陽（神都）', 112.45, 34.62, 3, ['wu-zetian'], ['tang'],
      '690年、67歳の武后は自ら皇帝となり、国号を周と改めた。洛陽を神都とよび、密告を奨励して反対派をきびしく処罰した。一方で科挙を重んじ、狄仁傑ら家柄にとらわれない有能な人材を登用した。',
      '690年、67歳の武后は、ついに自ら皇帝の位につきます。国の名を唐から周に改め、洛陽を神の都、神都とよびました。中国の歴史で、ただ一人の女性皇帝の誕生です。彼女は都に密告の箱を置き、反対派を残酷な役人に取り調べさせました。その一方で、科挙で選ばれた人びとを重く用い、家柄にとらわれず有能な人材を登用しました。宰相の狄仁傑もその一人です。',
      { marks: [{ name: '長安', lon: 108.94, lat: 34.26 }] }),
    S(698, '後継ぎの悩み', '洛陽', 112.45, 34.62, 3, ['wu-zetian'], ['tang'],
      '武后は後継ぎを、自分の武氏の甥にするか、李氏の息子にするかで悩んだ。母と子のきずなは甥とはくらべられないという狄仁傑の説得を受け、698年、退けていた中宗を皇太子にもどした。',
      '年老いた女帝の悩みは、後継ぎでした。自分の一族、武氏の甥に位をゆずれば周は続きます。しかし、息子たちは李氏、つまり唐の皇族です。宰相の狄仁傑は言いました。甥が叔母を先祖としてまつった例を聞いたことがありません。息子ならば、母をまつり続けるでしょう。698年、女帝は、かつて自分が退けた息子の中宗を、都に呼びもどして皇太子としました。',
      {}),
    S(705, '名を刻まない碑', '乾陵', 108.22, 34.57, 3, ['wu-zetian'], ['tang'],
      '705年、宰相らのクーデタで退位させられ、唐が復活した。その年の暮れ、82歳で亡くなる。遺言で皇帝の称号を取り去り、高宗の皇后として乾陵に葬られた。墓前には文字のない無字碑が立っている。',
      '705年、病に伏せる80歳をこえた女帝のもとに、宰相たちが兵を率いて押し入り、退位をせまりました。唐が復活し、その年の暮れ、彼女は洛陽で亡くなります。遺言で皇帝の称号を取り去り、高宗の皇后として乾陵に一緒に葬られました。墓の前には、何も刻まれていない大きな石碑が立っています。自分の評価は後世にまかせたのだとも言われますが、本当の理由はわかっていません。',
      { marks: [{ name: '洛陽（上陽宮で死去）', lon: 112.45, lat: 34.62 }, { name: '長安', lon: 108.94, lat: 34.26 }] })
  ]
},
// ---------- サラディン ----------
{
  id: 'life-saladin', kind: 'person', person: 'saladin', title: 'サラディンの生涯', period: '1138〜1193年',
  region: 'west', view: 'orient', tags: ['tankyu'],
  summary: 'クルド人の軍人の家に生まれたサラディンは、気の進まないエジプト行きから王朝の創始者となり、十字軍からイェルサレムを取りもどした。敵からも尊敬された寛大さと、財産を残さなかった最期までをたどる。',
  steps: [
    S(1138, '追われる一家に生まれる', 'ティクリート', 43.68, 34.61, 5, ['saladin'], ['abbasid', 'seljuk'],
      'サラディン（サラーフ=アッディーン）は、ティグリス川ぞいのティクリートで、城の守備隊長を務めるクルド人の家に生まれた。おじの起こした事件で一家は町を追われ、北シリアの君主ザンギーに仕えることになった。',
      '物語は1138年、ティグリス川のほとりの町ティクリートから始まります。サラディンの父アイユーブは、この町の城をあずかるクルド人の軍人でした。ところが、おじのシールクーフが人を殺す事件を起こし、一家は町を追われます。その夜にサラディンが生まれたという話も伝わっています。一家はシリアの君主ザンギーのもとに身を寄せました。',
      { routes: [{ name: '一家の移動', color: '#2e7d32', pts: [[43.68, 34.61], [43.13, 36.34], [38.8, 36.2], [36.29, 33.51]] }],
        marks: [{ name: 'モスル', lon: 43.13, lat: 36.34 }] }),
    S(1164, '気の進まないエジプト行き', 'アレクサンドリア', 29.92, 31.20, 8, ['saladin'], ['fatimid', 'crusader'],
      'ダマスクスで育ったサラディンは、おじシールクーフに従い、ヌール=アッディーンの命でエジプトへ遠征した。本人は乗り気ではなかった。1167年にはアレクサンドリアで十字軍とエジプト軍の包囲に耐えぬいた。',
      'ダマスクスで育ったサラディンは、学問や乗馬を好む青年でした。1164年、主君ヌール=アッディーンの命令で、おじのシールクーフがエジプト遠征に向かうと、サラディンも同行させられます。のちに彼は、死に向かって引かれていくような気持ちだったと語ったと伝えられています。1167年には、地中海の港町アレクサンドリアを守り、十字軍の包囲を3か月耐えぬきました。',
      { routes: [{ name: 'エジプト遠征', color: '#2e7d32', pts: [[36.29, 33.51], [35.5, 31.0], [33.0, 30.6], [31.24, 30.04], [29.92, 31.2]] }],
        marks: [{ name: 'カイロ', lon: 31.24, lat: 30.04 }] }),
    S(1169, '31歳の宰相', 'カイロ', 31.24, 30.04, 3, ['saladin'], ['fatimid', 'ayyubid'],
      'おじの急死で、31歳のサラディンがファーティマ朝の宰相となった。このとき彼は酒や遊びをやめ、信仰と政務に打ちこむようになったという。1171年にはファーティマ朝を終わらせ、スンナ派の信仰を回復した。',
      '1169年、エジプトの宰相となったおじが、わずか2か月で急死します。あとをついだのは、まだ31歳のサラディンでした。周囲は若くて扱いやすいと考えたのかもしれません。しかし、このときから彼は酒や遊びをやめ、信仰と政治に打ちこむようになったといわれます。1171年、シーア派のファーティマ朝を終わらせ、エジプトにアッバース朝カリフの権威とスンナ派の信仰を回復しました。',
      { marks: [{ name: 'カイロの城塞（のちに建設）', lon: 31.26, lat: 30.03 }] }),
    S(1174, 'ダマスクスへ', 'ダマスクス', 36.29, 33.51, 5, ['saladin'], ['ayyubid', 'crusader'],
      '主君ヌール=アッディーンとの間には緊張が高まっていたが、1174年にヌール=アッディーンが死去した。サラディンはダマスクスに入ってシリアを支配下におき、エジプトとシリアで十字軍国家をはさむ形をつくった。',
      'エジプトで力をつけるサラディンを、主君ヌール=アッディーンは警戒し始めます。二人の対決は避けられないと思われました。ところが1174年、ヌール=アッディーンが急死します。サラディンはすぐにダマスクスに入り、シリアを支配下に置きました。これで、エジプトとシリアの両側から、地中海沿岸の十字軍国家をはさみこむ形ができあがりました。',
      { routes: [{ name: 'シリアへ', color: '#2e7d32', pts: [[31.24, 30.04], [33.8, 30.6], [35.7, 31.5], [36.29, 33.51]] }],
        marks: [{ name: 'イェルサレム王国', lon: 35.23, lat: 31.78 }] }),
    S(1176, '暗殺者の短剣', 'マスヤーフ', 36.35, 35.06, 3, ['saladin'], ['ayyubid'],
      'シリアの山地に城をかまえるニザール派（いわゆる暗殺教団）は、サラディンを二度ねらった。彼がマスヤーフ城を包囲すると、ある朝、枕元に毒をぬった短剣と警告の手紙が置かれていたと伝えられる。',
      'サラディンをねらったのは、十字軍だけではありませんでした。シリアの山の城にこもるニザール派は、要人の暗殺で知られ、ヨーロッパでは暗殺教団とよばれました。サラディンは二度襲われ、かぶとのおかげで命拾いしています。1176年、彼が本拠地のマスヤーフ城を囲むと、ある朝、寝床のそばに短剣と警告の手紙が置かれていたと伝えられています。彼は包囲をとき、和解しました。',
      {}),
    S(1187, 'ヒッティーンの戦い', 'ヒッティーン', 35.45, 32.80, 2, ['saladin'], ['ayyubid', 'crusader'],
      '休戦中に巡礼の隊商を襲ったルノー=ド=シャティヨンへの怒りから、サラディンは決戦を決めた。7月、水のない丘に十字軍を追いこんで大勝し、ルノーは自ら斬ったが、捕虜のイェルサレム王ギーは「王は王を殺さない」と許した。',
      '休戦中にもかかわらず、十字軍の騎士ルノーはイスラーム教徒の巡礼の隊商を襲いました。サラディンは激しく怒り、決戦を決意します。1187年7月、真夏のガリラヤ湖の西、ヒッティーンの丘で、水をたたれた十字軍は大敗しました。サラディンはルノーを自らの手で斬りました。しかし、ふるえる王ギーには冷たい水を与え、王は王を殺さないものだと言って命を助けたと伝えられています。',
      { marks: [{ name: 'ガリラヤ湖', lon: 35.58, lat: 32.82 }, { name: 'ティベリアス', lon: 35.53, lat: 32.79 }] }),
    S(1187, 'イェルサレムの奪回', 'イェルサレム', 35.23, 31.78, 0.6, ['saladin'], ['ayyubid', 'crusader'],
      '10月、約90年ぶりにイスラーム側がイェルサレムを取りもどした。1099年の十字軍による虐殺とは対照的に、サラディンは身代金を払った住民の退去を認め、払えない多くの人も解放したと伝えられる。',
      '1187年10月、サラディンはイェルサレムに入城しました。88年前の1099年、第1回十字軍がこの町を占領したときには、住民の大虐殺が起きていました。サラディンは仕返しをしませんでした。身代金を払った住民には、財産を持って町を出ることを認めます。払えない貧しい人びとの多くも、彼や弟の判断で解放されたと伝えられています。この寛大さは、敵のヨーロッパでも語りつがれました。',
      { marks: [{ name: '岩のドーム', lon: 35.2354, lat: 31.778 }, { name: '聖墳墓教会', lon: 35.2296, lat: 31.7784 }] }),
    S(1191, '獅子心王リチャードとの対決', 'アルスフ', 34.82, 32.20, 3, ['saladin'], ['ayyubid', 'crusader'],
      '第3回十字軍がアッコンを奪い返し、イギリス王リチャード1世は捕虜約2700人を処刑した。アルスフの戦いでサラディンは敗れたが、病のリチャードに果物や雪を贈ったという騎士道の話も伝わる。',
      'イェルサレムを失ったヨーロッパは、第3回十字軍を送りこみます。中心は、イギリス王リチャード1世、獅子心王です。1191年、十字軍は2年がかりの包囲の末にアッコンを奪い、リチャードは捕虜およそ2700人を処刑しました。アルスフの戦いではサラディンも敗れます。それでも、病に倒れたリチャードに、サラディンが果物や冷たい雪を贈ったという話が伝わっています。',
      { routes: [{ name: '十字軍の南下', color: '#555555', pts: [[35.08, 32.93], [34.95, 32.6], [34.82, 32.2], [34.75, 32.05]] }],
        marks: [{ name: 'アッコン', lon: 35.08, lat: 32.93 }, { name: 'ヤッファ', lon: 34.75, lat: 32.05 }] }),
    S(1192, '休戦協定', 'ラムラ', 34.87, 31.93, 3, ['saladin'], ['ayyubid', 'crusader'],
      'どちらも決定的な勝利を得られないまま、1192年9月、両者は休戦協定を結んだ。イェルサレムはイスラーム側が保ち、キリスト教徒の巡礼は認められた。リチャードとサラディンは一度も直接会わなかった。',
      '戦いは一進一退となり、どちらも疲れきっていました。リチャードは、自分の妹とサラディンの弟を結婚させてイェルサレムを共同で治めるという、驚くような案まで出したといわれます。1192年9月、両者は3年の休戦を結びました。イェルサレムはイスラーム側が保ち、キリスト教徒の巡礼は自由とされます。ふしぎなことに、二人の英雄は最後まで一度も顔を合わせませんでした。',
      { marks: [{ name: 'イェルサレム', lon: 35.23, lat: 31.78 }] }),
    S(1193, '何も残さなかった王', 'ダマスクス', 36.29, 33.51, 3, ['saladin'], ['ayyubid'],
      '1193年3月、サラディンはダマスクスで熱病のため亡くなった。55歳だった。財産のほとんどを施しや戦費に使っていたため、手元には金貨1枚と銀貨47枚しかなく、葬儀の費用は借金でまかなわれたという。',
      '休戦の翌年、1193年3月、サラディンはダマスクスで熱病にかかり、55歳で亡くなりました。王の金庫を開けた家臣たちは驚きます。残っていたのは、金貨1枚と銀貨47枚だけでした。彼は財産のほとんどを、貧しい人への施しや戦いの費用に使ってしまっていたのです。葬儀の費用は借金でまかなわれたと伝えられています。その墓は、今もウマイヤ=モスクのそばにあります。',
      { marks: [{ name: 'ウマイヤ=モスク', lon: 36.306, lat: 33.511 }] })
  ]
},
// ---------- チンギス=カン ----------
{
  id: 'life-genghis', kind: 'person', person: 'genghis', title: 'チンギス=カンの生涯', period: '1162〜1227年',
  region: 'inner', view: 'inner', tags: ['tankyu'],
  summary: '父を毒殺され、一族に見捨てられた少年テムジンは、仲間を一人ずつ増やしてモンゴル高原を統一し、チンギス=カンとなった。苦難の少年時代から、ユーラシアをまたぐ大遠征、そして秘密の墓までをたどる。',
  steps: [
    S(1162, '血の塊をにぎって', 'オノン川流域', 111.50, 49.30, 8, ['genghis'], [],
      'テムジン（のちのチンギス=カン）は、モンゴル部の有力者イェスゲイの子として、オノン川のほとりで生まれた。生まれたとき右手に血の塊をにぎっていたと『元朝秘史』は伝えている。生年には諸説がある。',
      '物語は1162年ごろ、モンゴル高原の北東、オノン川のほとりから始まります。モンゴル部の有力者イェスゲイに男の子が生まれ、テムジンと名づけられました。モンゴルの歴史書、元朝秘史は、赤ん坊が右手に血の塊をにぎって生まれてきたと伝えています。人びとはこれを、のちの征服者のしるしだと語りました。生まれた年には、ほかにもいくつかの説があります。',
      { marks: [{ name: 'ケルレン川', lon: 112.5, lat: 47.8 }] }),
    S(1171, '父の死、見捨てられた家族', 'オノン川流域', 111.00, 49.00, 8, ['genghis'], [],
      '9歳ごろ、許婚ボルテの家からの帰り道、父イェスゲイはタタル部に毒を盛られて死んだ。部族の人びとは残された母子を見捨てて去り、一家は草の根や魚で飢えをしのぎ、苦しい少年時代を送った。',
      '9歳ごろ、父はテムジンを、のちに妻となるボルテの家にあずけました。その帰り道、父は敵のタタル部の宴で毒を盛られ、亡くなります。すると部族の人びとは、残された母と幼い子どもたちを見捨てて去っていきました。一家は草の根や野生の実、川の魚で命をつなぎます。この経験から、彼は血のつながりよりも信頼できる仲間を何より大切にするようになりました。',
      {}),
    S(1184, 'さらわれた妻を取りもどす', 'セレンゲ川流域', 106.50, 50.50, 10, ['genghis'], [],
      'このころ、新妻ボルテがメルキト部にさらわれた。テムジンは父の盟友だったケレイト部のトオリルと、幼なじみのジャムカに助けを求め、ボルテを取りもどした。テムジンの名は高原に知られるようになった。',
      '若いテムジンに、また試練がおそいます。結婚したばかりの妻ボルテが、メルキト部にさらわれたのです。テムジンは、父の盟友だったケレイト部の長トオリルと、幼いころ兄弟の誓いを結んだジャムカに助けを求めました。三人の軍はメルキトをおそい、ボルテを取りもどします。仲間を集めて大きな相手に挑む。これが、テムジンの戦い方の原点になりました。',
      { routes: [{ name: '救出の進軍', color: '#1565c0', pts: [[111.0, 49.0], [109.0, 49.5], [106.5, 50.5]] }] }),
    S(1204, '盟友との決別', 'ハンガイ山地', 101.00, 47.50, 12, ['genghis'], [],
      'テムジンはやがてケレイト部のトオリル、ついでナイマン部を破った。ライバルとなったジャムカは部下に裏切られて引き渡されたが、テムジンは裏切った部下を処刑し、ジャムカの願いどおり血を流さない形で死なせたと伝えられる。',
      '力をつけたテムジンは、やがて恩人トオリルと対立し、これを破ります。1204年には西のナイマン部も倒しました。かつての兄弟、ジャムカは敵となり、最後は自分の部下に裏切られてテムジンのもとに引き渡されます。テムジンは、主人を売った部下たちを処刑しました。そして、ジャムカの願いを聞き入れ、モンゴルの作法で血を流さずに死なせたと元朝秘史は伝えています。',
      { routes: [{ name: 'ナイマン遠征', color: '#1565c0', pts: [[111.0, 48.5], [106.0, 47.5], [101.0, 47.5]] }] }),
    S(1206, 'チンギス=カンの誕生', 'オノン川の源流', 110.50, 48.80, 8, ['genghis'], ['mongol'],
      '1206年、オノン川の源流で開かれたクリルタイで、テムジンはチンギス=カンの称号を受けた。遊牧民を千戸ずつの単位に組み直し、信頼する仲間をその長に任じた。血筋より忠誠で動く国家の誕生だった。',
      '1206年の春、オノン川の源流に高原じゅうの有力者が集まり、クリルタイとよばれる大集会が開かれました。テムジンはここでチンギス=カンという称号を受けます。彼は古い部族のまとまりをばらし、遊牧民を千戸ずつの集団に組み直しました。その長には、苦しい時代をともにした仲間たちを任命します。羊飼いや鍛冶屋の息子も、能力と忠誠しだいで将軍になれたのです。',
      {}),
    S(1215, '金の都を落とす', '中都（北京）', 116.40, 39.90, 10, ['genghis'], ['mongol', 'jin', 'xixia'],
      '1211年、チンギスは長年モンゴルを圧迫してきた金への遠征を始め、1215年に都の中都を攻め落とした。降伏した契丹人の耶律楚材の知識と人柄を見こみ、そばに置いて重く用いた。',
      '1211年、チンギスは、長いあいだモンゴルの部族を分断し、支配してきた金への遠征を始めます。モンゴル軍は長城をこえ、1215年には金の都、中都を攻め落としました。ここでチンギスは、金に仕えていた契丹人の学者、耶律楚材に出会います。背が高く、ひげの長いこの人物を気に入り、側近にしました。征服した民の知恵を使うことも、モンゴルの強さでした。',
      { routes: [{ name: '金への遠征', color: '#1565c0', pts: [[110.5, 48.8], [111.5, 44.5], [113.0, 41.0], [115.5, 40.4], [116.4, 39.9]] }] }),
    S(1219, 'オトラルの悲劇', 'オトラル', 68.30, 42.85, 10, ['genghis'], ['mongol', 'khwarazm'],
      'チンギスは西のホラズム=シャー朝に通商を求め、約450人の隊商を送ったが、オトラルの総督が彼らを殺して品物を奪った。抗議の使者まで殺されたことに怒り、1219年、チンギスは西方遠征に出発した。',
      'チンギスは、西の大国ホラズム=シャー朝と仲良く商売をしたいと考え、およそ450人の隊商を送りました。ところが国境の町オトラルの総督は、彼らをスパイだとして殺し、品物を奪ってしまいます。チンギスが抗議の使者を送ると、その使者まで殺されました。チンギスは山に登り、3日3晩祈ったと伝えられています。1219年、モンゴル軍は西へ向かいました。',
      { routes: [{ name: '西方遠征', color: '#1565c0', pts: [[107.0, 47.5], [96.0, 47.0], [87.0, 46.5], [80.0, 44.0], [72.0, 43.5], [68.3, 42.85]] }] }),
    S(1220, 'ブハラとサマルカンド', 'サマルカンド', 66.97, 39.65, 8, ['genghis'], ['mongol', 'khwarazm'],
      'ブハラ、サマルカンドが次々と陥落した。降伏した町は許し、抵抗した町は徹底的に破壊するという方針で、征服は急速に進んだ。ホラズムの王ムハンマドはカスピ海の島に逃れ、そこで死んだ。',
      '1220年、モンゴル軍はブハラ、そして都サマルカンドを次々に落としました。抵抗した町は徹底的に破壊され、降伏した町は許される。このうわさが広まり、多くの町が戦わずに門を開きました。ペルシアの歴史家は、ブハラでチンギスが、私は神がお前たちに下した罰だと語ったと書いています。ホラズムの王は逃げまどい、カスピ海の小島で病死しました。',
      { routes: [{ name: 'モンゴル軍', color: '#1565c0', pts: [[68.3, 42.85], [64.42, 39.77], [66.97, 39.65]] }],
        marks: [{ name: 'ブハラ', lon: 64.42, lat: 39.77 }] }),
    S(1221, 'インダス河畔の敵の王子', 'インダス河畔', 72.20, 33.80, 8, ['genghis'], ['mongol', 'khwarazm'],
      'ホラズムの王子ジャラール=アッディーンを追いつめたが、王子は馬ごとインダス川に飛びこんで逃げた。チンギスは部下に矢を射させず、父親ならこのような息子をもつべきだと息子たちに語ったと伝えられる。',
      'ホラズムの王子ジャラール=アッディーンは、最後まで抵抗を続けました。1221年、チンギスはインダス川の岸で彼を追いつめます。すると王子は、馬に乗ったまま高い崖から川へ飛びこみ、向こう岸へ泳ぎわたりました。チンギスは矢を射ようとする部下を止め、息子たちに向かって、父親ならこのような息子をもつべきだと言ったと伝えられています。敵の勇気をたたえる人でもあったのです。',
      { routes: [{ name: '追撃', color: '#1565c0', pts: [[66.97, 39.65], [66.9, 36.76], [69.17, 34.53], [72.2, 33.8]] }] }),
    S(1222, '不老不死の薬はあるか', 'ヒンドゥークシュ山脈', 69.20, 35.00, 6, ['genghis'], ['mongol'],
      'チンギスは中国から道士の長春真人（丘処機）を呼び寄せ、ヒンドゥークシュの陣営で会った。長生きの薬はあるかと問うと、長春真人は、命を守る道はあるが不老不死の薬はないと答えた。チンギスはその正直さを喜んだという。',
      '60歳近くになったチンギスは、ある願いをもちます。中国の山東から、名高い道士、長春真人を何千キロもかけて呼び寄せたのです。1222年、ヒンドゥークシュ山脈の陣営で会うと、チンギスはたずねました。不老不死の薬はあるか。長春真人は答えます。命を守る方法はありますが、長生きの薬はありません。チンギスは怒らず、その正直さを喜んだと記録されています。',
      { marks: [{ name: 'バーミヤーン', lon: 67.8, lat: 34.8 }] }),
    S(1227, '秘密の墓', '六盤山', 106.20, 35.60, 12, ['genghis'], ['mongol', 'xixia', 'jin'],
      '西夏が約束した援軍を出さなかったため、チンギスは西夏遠征に向かった。狩りの最中に落馬して体を痛め、1227年、六盤山のあたりで死去した。遺体はモンゴル高原に運ばれ、墓の場所は今もわかっていない。',
      'ホラズム遠征のとき、西夏は援軍を出す約束を破りました。チンギスは帰国後、西夏遠征に向かいます。その途中、野生の馬の狩りで落馬し、体を痛めました。それでも引き返さず、1227年、六盤山のあたりで亡くなります。西夏はその直後に滅びました。遺体はひそかにモンゴル高原へ運ばれ、墓の場所は秘密にされました。今もだれも、その場所を知りません。',
      { routes: [{ name: '西夏遠征', color: '#1565c0', pts: [[107.0, 47.5], [106.5, 42.0], [106.27, 38.47], [106.2, 35.6]] }],
        marks: [{ name: '中興府（西夏の都）', lon: 106.27, lat: 38.47 }] })
  ]
},
// ---------- フビライ ----------
{
  id: 'life-kublai', kind: 'person', person: 'kublai', title: 'フビライの生涯', period: '1215〜1294年',
  region: 'east', view: 'eastasia', tags: ['tankyu'],
  summary: 'チンギス=カンの孫フビライは、中国の学者を側近に迎えて漢地を治め、兄の死後、弟との争いに勝ってカアンとなった。大都の建設、南宋の征服、日本遠征の失敗まで、草原と中国をつないだ皇帝の一生をたどる。',
  steps: [
    S(1224, '祖父の初めての狩り', 'モンゴル高原', 107.00, 47.50, 14, ['kublai', 'genghis'], ['mongol'],
      'フビライはチンギス=カンの末子トルイの子として生まれた。西方遠征から帰る祖父を迎えたとき、11歳のフビライが初めての狩りでしとめた獲物の脂を、チンギスが自ら孫の指にぬってやったと伝えられる。',
      '物語は1224年、西方遠征から帰ってくるチンギス=カンを、孫たちが迎えに出た場面から始まります。フビライはチンギスの末っ子トルイの息子で、このとき11歳でした。この旅で、彼は初めての狩りでウサギをしとめます。モンゴルには、初めての獲物の脂を子どもの指にぬる習わしがありました。祖父チンギスは、自らフビライの指に脂をぬってやったと伝えられています。',
      { marks: [{ name: 'オノン川', lon: 111.5, lat: 49.3 }] }),
    S(1251, '漢地をまかされる', '金蓮川', 116.20, 42.20, 8, ['kublai'], ['mongol'],
      '兄モンケがカアンになると、フビライは漢地（中国北部）の統治をまかされた。金蓮川に陣営をおき、劉秉忠ら中国の学者や僧を側近に招いた。略奪よりも、農民から安定して税をとる方が国は豊かになると学んだ。',
      '1251年、兄のモンケがモンゴル帝国のカアンになり、フビライは中国北部、漢地の統治をまかされます。フビライは、草原と農地の境目にあたる金蓮川に陣営をおき、中国の学者や僧を次々に招きました。草原の戦士たちは、農地を牧場にすればよいと考えがちでした。しかしフビライは、農民が安心して働ける方が、ずっと多くの税が集まることを学んでいきます。',
      { marks: [{ name: 'カラコルム', lon: 102.83, lat: 47.2 }, { name: '中都（北京）', lon: 116.4, lat: 39.9 }] }),
    S(1253, '大理国の征服', '大理', 100.20, 25.60, 10, ['kublai'], ['mongol', 'dali'],
      'フビライは南宋を背後から囲むため、チベット高原の東の険しい山岳地帯を進み、雲南の大理国を征服した。側近の進言を受け、降伏した都では人びとを殺さないよう命じたと伝えられる。',
      '1253年、フビライは大軍を率いて、南宋を西から回りこむ遠征に出ます。チベット高原の東のふちの険しい山々をこえ、雲南の大理国に攻めこみました。羊の皮の袋で大河をわたったといわれる、苦しい行軍でした。側近の学者は、人を殺さないことこそ天下を得る道だと説きます。フビライはこれを聞き入れ、降伏した都、大理では住民を殺さないよう命じたと伝えられています。',
      { routes: [{ name: '大理遠征', color: '#1565c0', pts: [[106.27, 38.47], [103.8, 36.1], [102.5, 33.0], [101.0, 29.0], [100.2, 25.6]] }] }),
    S(1259, '兄の死の知らせ', '鄂州（武昌）', 114.30, 30.59, 10, ['kublai'], ['mongol', 'nansong'],
      'フビライが長江中流の鄂州を囲んでいたとき、兄モンケが四川の釣魚城攻めの陣中で死んだという知らせが届いた。弟アリクブケがカアンの位をねらっていると聞き、フビライは南宋と和を結んで北へ急いだ。',
      '1259年、フビライは南宋を攻め、長江の中流の鄂州、今の武昌を包囲していました。そこへ、兄モンケが四川の釣魚城を攻める途中で亡くなったという知らせが届きます。高原の都カラコルムでは、末の弟アリクブケが次のカアンになる準備を進めていました。ぐずぐずしてはいられません。フビライは南宋と急いで和を結び、軍を北へ返しました。',
      { routes: [{ name: '北への帰還', color: '#1565c0', pts: [[114.3, 30.59], [114.35, 34.79], [116.4, 39.9], [116.18, 42.36]] }],
        marks: [{ name: '釣魚城（モンケ死去）', lon: 106.3, lat: 30.0 }] }),
    S(1260, '兄弟のカアン争い', '上都（開平）', 116.18, 42.36, 14, ['kublai'], ['mongol'],
      '1260年、フビライは開平（のちの上都）でカアンに即位したが、カラコルムでも弟アリクブケが即位した。4年の戦いでフビライが勝ったが、帝国西方の一族はそれぞれの国の自立を強めていった。',
      '1260年、フビライは自分の陣営の開平、のちの上都でクリルタイを開き、カアンになりました。ところが同じ年、高原の都カラコルムでも、弟のアリクブケがカアンを名のります。モンゴル帝国にカアンが二人並んだのです。戦いは4年続き、食料を中国からおさえたフビライが勝ちました。しかし、この争いをきっかけに、西方の一族の国々はそれぞれの道を歩み始めます。',
      { routes: [{ name: 'アリクブケとの戦い', color: '#1565c0', pts: [[116.18, 42.36], [111.0, 45.0], [102.83, 47.2]] }],
        marks: [{ name: 'カラコルム（アリクブケ）', lon: 102.83, lat: 47.2 }] }),
    S(1271, '大都と「元」', '大都（北京）', 116.40, 39.90, 3, ['kublai'], ['yuan'],
      'フビライは金の中都の東北に、計画都市の大都を建設した。1271年、中国の古典『易経』の言葉から国号を「元」と定め、中国の王朝の形を整えた。大都は運河と海の道で江南と結ばれた。',
      'フビライは、草原と中国の境に近い今の北京に、新しい都を建てさせます。大都です。碁盤の目のように道が走り、中心には宮殿、周囲を城壁が囲む計画都市でした。1271年、フビライは中国の古典、易経の言葉から、国の名を元と定めます。モンゴルの君主であると同時に、中国の皇帝でもある。冬は大都、夏は草原の上都ですごす暮らしが、それを物語っています。',
      { marks: [{ name: '上都（夏の都）', lon: 116.18, lat: 42.36 }] }),
    S(1274, '海をこえる遠征', '博多湾', 130.40, 33.60, 6, ['kublai'], ['yuan', 'goryeo', 'japan-pre'],
      'フビライは日本に何度も使者を送って服属を求めたが、鎌倉幕府は応じなかった。1274年、高麗に船をつくらせ、元・高麗の連合軍が博多湾に上陸した（文永の役）。軍は1日の戦いのあと撤退した。',
      'フビライは日本に何度も国書を送り、つきあいを求めました。しかし鎌倉幕府の北条時宗は応じません。1274年、フビライは高麗に命じて大急ぎで船をつくらせ、元と高麗の連合軍およそ3万が博多湾に上陸しました。文永の役です。集団で戦い、火薬の武器を使う元軍に、武士たちは苦戦します。しかし軍は1日の戦いのあと船にもどり、引き揚げていきました。',
      { routes: [{ name: '元・高麗軍', color: '#1565c0', pts: [[129.1, 35.1], [129.3, 34.4], [129.7, 33.75], [130.4, 33.6]] }],
        marks: [{ name: '対馬', lon: 129.3, lat: 34.4 }, { name: '壱岐', lon: 129.7, lat: 33.8 }] }),
    S(1275, 'ヴェネツィアの若者', '上都', 116.18, 42.36, 4, ['kublai', 'marco-polo'], ['yuan'],
      '夏の都上都に、ヴェネツィアの商人ポーロ兄弟が、21歳のマルコを連れてやってきた。フビライは外国人を役人として積極的に使い、マルコものちに各地への使いを命じられたと語っている。',
      '1275年ごろ、夏の都の上都に、はるばるヨーロッパから3人の商人がたどりつきます。ヴェネツィアのポーロ兄弟と、息子の若いマルコでした。フビライは、出身にこだわらず、役に立つ外国人を積極的に用いる君主でした。中央アジアや西アジア出身の色目人が財政を担い、イタリアの若者にも仕事が与えられます。マルコの目に映ったフビライは、世界一豊かで力のある君主でした。',
      {}),
    S(1276, '臨安の無血開城', '臨安（杭州）', 120.16, 30.27, 8, ['kublai'], ['yuan', 'nansong'],
      '襄陽を5年がかりで落とした元軍は、将軍バヤンのもとで長江を下り、1276年、南宋の都臨安を占領した。大きな殺りくはなく、幼い皇帝は大都へ送られた。1279年、南宋は崖山の戦いで完全に滅んだ。',
      '元軍は、南宋の守りのかなめ、襄陽を5年がかりで攻め落とし、長江を下りました。総大将のバヤンに、フビライは、むやみに人を殺すなと命じていたといわれます。1276年、南宋の都、臨安は戦わずに降伏し、幼い皇帝は北の大都へ送られました。南宋の残りの人びとは南へ逃れて抵抗を続けますが、1279年、崖山の海戦で滅び、中国全土が元のものとなりました。',
      { routes: [{ name: 'バヤンの進軍', color: '#1565c0', pts: [[112.14, 32.04], [114.3, 30.59], [117.0, 30.5], [118.78, 32.06], [120.16, 30.27]] }],
        marks: [{ name: '襄陽', lon: 112.14, lat: 32.04 }, { name: '崖山', lon: 113.05, lat: 22.2 }] }),
    S(1281, '二度目の失敗と悲しみ', '鷹島（伊万里湾）', 129.75, 33.43, 5, ['kublai'], ['yuan', 'goryeo', 'japan-pre'],
      '1281年、元は南宋の兵をふくむ約14万の大軍で再び日本を攻めたが、石築地（防塁）と武士の抵抗にはばまれ、台風で大損害を受けた（弘安の役）。同じ年、最愛の皇后チャブイが亡くなった。',
      '1281年、フビライは二度目の日本遠征を命じます。今度は、降伏した南宋の兵をふくむ14万ともいわれる大軍でした。しかし博多湾には石の防塁が築かれ、武士たちは夜も小舟で敵船を襲います。海上で足止めされた船団は、鷹島の沖で台風に襲われ、壊滅しました。同じ年、フビライが深く愛し、頼りにしていた皇后チャブイが亡くなります。これ以後、皇帝は酒におぼれがちになったといいます。',
      { routes: [{ name: '東路軍', color: '#1565c0', pts: [[129.1, 35.1], [129.3, 34.4], [130.4, 33.65]] }, { name: '江南軍', color: '#5c6bc0', pts: [[121.55, 29.87], [126.0, 31.5], [129.75, 33.43]] }],
        marks: [{ name: '博多湾', lon: 130.4, lat: 33.6 }] }),
    S(1294, '大都に死す', '大都（北京）', 116.40, 39.90, 20, ['kublai'], ['yuan'],
      '晩年のフビライは、ベトナムやジャワへの遠征にも失敗し、後継ぎと決めていた皇太子にも先立たれた。1294年、大都で80歳で死去。遺体は草原に運ばれて葬られ、墓の場所は知られていない。',
      '晩年のフビライは、ベトナムやジャワへの遠征にも失敗しました。後継ぎと決めていた皇太子も先に亡くなります。1294年、フビライは大都で80歳の生涯を終えました。遺体は祖父と同じように草原へ運ばれ、ひそかに葬られました。彼の時代、大都は陸の道と海の道で世界と結ばれ、紙幣が使われる国際都市となりました。その都は今、中国の首都、北京として続いています。',
      { marks: [{ name: '上都', lon: 116.18, lat: 42.36 }, { name: 'ジャワ（遠征）', lon: 112.5, lat: -7.5 }, { name: '大越（遠征）', lon: 105.85, lat: 21.03 }] })
  ]
},
// ---------- マルコ=ポーロ ----------
{
  id: 'life-marco-polo', kind: 'person', person: 'marco-polo', title: 'マルコ=ポーロの生涯', period: '1254〜1324年',
  region: 'europe', view: 'eurasia', tags: ['tankyu'],
  summary: 'ヴェネツィアの商人の子マルコ=ポーロは、17歳で父とおじに連れられて東方へ旅立ち、フビライに仕えて17年を過ごした。往きは陸の道、帰りは海の道。ユーラシアを一周した若者の人生と、獄中で生まれた一冊の本の物語。',
  steps: [
    S(1269, '15歳で父に会う', 'ヴェネツィア', 12.34, 45.44, 3, ['marco-polo'], ['venice'],
      'マルコが生まれたころ、父ニコロとおじマッテオは商売の旅に出ており、モンゴル帝国でフビライに会っていた。母を早くに亡くしたマルコは、15歳になった1269年、帰ってきた父と初めて対面した。',
      '物語は1269年、水の都ヴェネツィアから始まります。マルコ=ポーロが生まれたとき、父のニコロとおじのマッテオは、商売の旅で東方にいました。二人はなりゆきで、モンゴル帝国のフビライに会っていたのです。母を早く亡くしたマルコは、15歳になってようやく、帰ってきた父と初めて顔を合わせました。父たちは、フビライからローマ教皇あての手紙をあずかっていました。',
      { marks: [{ name: 'サン=マルコ広場', lon: 12.339, lat: 45.434 }] }),
    S(1271, '17歳の旅立ち', 'アッコン', 35.08, 32.93, 6, ['marco-polo'], ['crusader', 'venice'],
      '1271年、17歳のマルコは父とおじに連れられ、十字軍の拠点アッコンへわたった。ここで会った教皇特使が新しい教皇に選ばれ、フビライへの手紙と2人の修道士を託したが、修道士は途中で引き返してしまった。',
      '1271年、17歳のマルコは、父とおじに連れられて船出し、十字軍の拠点アッコンに着きます。ここで一行は、教皇の特使に会いました。その特使が、まもなく新しいローマ教皇に選ばれ、フビライあての手紙と二人の修道士を一行に託します。ところが修道士たちは、戦乱のうわさにおびえ、途中で引き返してしまいました。旅はポーロ家の3人で続けられることになります。',
      { routes: [{ name: '船旅', color: '#8e44ad', pts: [[12.34, 45.44], [15.5, 42.0], [20.0, 38.0], [26.0, 35.3], [32.0, 34.0], [35.08, 32.93]] }] }),
    S(1272, '縫い合わされた船', 'ホルムズ', 56.27, 27.10, 8, ['marco-polo'], ['ilkhan'],
      '一行はイランを南下してペルシア湾のホルムズに着き、海路で中国へ向かおうとした。しかし船は釘を使わず、ヤシの繊維で板を縫い合わせたもので、危険だと判断し、陸路を選びなおしたといわれる。',
      'アッコンからイル=ハン国の領内を南へ進み、一行はペルシア湾の入口の港、ホルムズに着きました。ここから船で中国へ向かう計画でした。ところが港の船を見て驚きます。板は鉄の釘を使わず、ヤシの実の繊維の糸で縫い合わせてあったのです。こんな船で大海をわたるのは危険だ。そう考えた一行は、陸の道で東へ向かうことに決めたといわれます。',
      { routes: [{ name: '陸路の旅', color: '#8e44ad', pts: [[35.08, 32.93], [38.0, 36.5], [44.0, 37.5], [46.29, 38.08], [51.4, 35.7], [55.0, 31.0], [56.27, 27.1]] }],
        marks: [{ name: 'タブリーズ', lon: 46.29, lat: 38.08 }] }),
    S(1273, '世界の屋根をこえる', 'パミール高原', 73.50, 37.50, 12, ['marco-polo'], [],
      'マルコはバダフシャーンで病にかかり、1年ほど療養したという。そのあとパミール高原をこえた。高い所では火の燃え方が弱く、料理に時間がかかると書き残しており、高地の空気のうすさに気づいていた。',
      'ホルムズから引き返した一行は、イランの砂漠をこえ、アフガニスタンの山地バダフシャーンに入ります。ここでマルコは病にかかり、1年ほど山の空気の中で療養したといわれます。回復すると、いよいよ世界の屋根、パミール高原です。マルコは、ここでは火の燃え方が弱く、ものがなかなか煮えないと書いています。空気のうすさを、料理で感じとったのです。',
      { routes: [{ name: '東への道', color: '#8e44ad', pts: [[56.27, 27.1], [59.6, 36.3], [66.9, 36.76], [70.5, 37.0], [73.5, 37.5], [75.99, 39.47]] }],
        marks: [{ name: 'カシュガル', lon: 75.99, lat: 39.47 }, { name: 'バダフシャーン', lon: 70.8, lat: 37.0 }] }),
    S(1275, 'フビライに会う', '上都', 116.18, 42.36, 12, ['marco-polo', 'kublai'], ['yuan'],
      'タリム盆地南辺のオアシスをつなぎ、ゴビ砂漠をこえて、出発から3年半後、一行はフビライの夏の都上都に着いた。フビライは再会を喜び、マルコを気に入って使者として用いたと、マルコは語っている。',
      'カシュガルから、タリム盆地の南の縁のオアシスを伝い、敦煌をへてゴビ砂漠をこえます。夜の砂漠では、仲間を呼ぶような声が聞こえ、迷う旅人がいると書き残しています。出発から3年半、一行はついにフビライの夏の都、上都にたどりつきました。フビライは兄弟との再会を喜び、21歳のマルコに目をとめます。ここから17年におよぶ中国での暮らしが始まりました。',
      { routes: [{ name: '砂漠の道', color: '#8e44ad', pts: [[75.99, 39.47], [79.92, 37.11], [88.0, 38.5], [94.66, 40.14], [100.5, 38.9], [107.0, 40.5], [116.18, 42.36]] }],
        marks: [{ name: '敦煌', lon: 94.66, lat: 40.14 }] }),
    S(1285, '天の都キンサイ', '杭州（キンサイ）', 120.16, 30.27, 4, ['marco-polo'], ['yuan'],
      'マルコは元の各地を旅したと語る。旧南宋の都杭州を「キンサイ（天の都）」とよび、運河と橋、にぎわう市場、紙幣の使用、燃える黒い石（石炭）など、ヨーロッパにない豊かさを驚きをこめて記した。',
      'マルコはフビライの使いとして、中国の各地を旅したと語っています。とくに心をうばわれたのは、元に降伏した南宋の旧都、杭州でした。マルコはこれをキンサイ、天の都とよび、町を運河が走り、たくさんの石の橋がかかっていると書きます。人びとは紙のお金で買い物をし、燃える黒い石で湯をわかしていました。石炭のことです。ヨーロッパの人には信じられない光景でした。',
      { lines: [{ name: '大運河', pts: [[116.4, 39.9], [117.2, 39.13], [116.6, 36.0], [118.0, 33.8], [119.42, 32.39], [120.3, 31.6], [120.16, 30.27]] }],
        marks: [{ name: '大都', lon: 116.4, lat: 39.9 }, { name: '揚州', lon: 119.42, lat: 32.39 }] }),
    S(1291, '王女を送る船団', '泉州', 118.59, 24.91, 6, ['marco-polo', 'kublai'], ['yuan'],
      '帰国を願い出ても許されなかったポーロ家に機会が来た。イル=ハン国の君主に嫁ぐ王女コケジンを送る船団の案内役に選ばれたのである。1291年ごろ、14隻の船団で港町泉州を出航した。',
      '年老いた父たちは帰国を願い出ますが、フビライはなかなか許しません。そこへ機会が訪れます。イル=ハン国の君主アルグンが妃をむかえることになり、王女コケジンを海路で送る一行に、旅なれたポーロ家が選ばれたのです。1291年ごろ、14隻の大船団が、世界有数の港町泉州を出航しました。マルコはこの町を、アレクサンドリアをしのぐ大港だと書いています。',
      { routes: [{ name: '帰りの海路', color: '#8e44ad', pts: [[118.59, 24.91], [113.5, 21.5], [109.0, 15.0], [105.0, 8.0], [103.0, 2.5], [97.1, 5.2]] }] }),
    S(1292, 'スマトラで5か月', 'スマトラ島', 97.10, 5.20, 10, ['marco-polo'], [],
      '船団は季節風を待つため、スマトラ島北部で5か月とどまった。マルコはこの島の港にイスラーム教徒の商人がいることを記録した。また一角獣を見たと書いたが、それはサイのことだった。',
      '船団は、インド洋をわたる季節風の向きが変わるのを待って、スマトラ島の北部で5か月を過ごしました。マルコは、この島の港町に、すでにイスラーム教を信じる人びとがいると記録しています。東南アジアのイスラーム化を伝える、早い時期の記録です。ヨーロッパの伝説の一角獣も見たと書きましたが、説明を読むと、どうやらサイのことでした。',
      { routes: [{ name: 'インド洋をわたる', color: '#8e44ad', pts: [[97.1, 5.2], [88.0, 5.5], [79.86, 6.93], [76.0, 9.5], [72.0, 17.0], [62.0, 24.0], [56.27, 27.1]] }] }),
    S(1294, 'フビライの死の知らせ', 'タブリーズ', 46.29, 38.08, 10, ['marco-polo', 'ghazan'], ['ilkhan'],
      '2年がかりでイランに着くと、花婿のアルグンはすでに死んでおり、王女はその子ガザンに嫁いだ。一行は旅の途中で、フビライの死の知らせを聞いた。出発した600人のうち、生き残ったのは18人だったという。',
      'ホルムズに着くまで、およそ2年かかりました。マルコによれば、出発したおよそ600人のうち、生き残ったのは18人だけでした。しかも花婿のアルグンは、すでに亡くなっていました。王女は、その息子ガザンに嫁ぐことになります。のちにイル=ハン国をイスラームの国に改める君主です。一行が旅の途中で聞いたのは、恩人フビライの死の知らせでした。',
      { routes: [{ name: 'イランを北上', color: '#8e44ad', pts: [[56.27, 27.1], [52.5, 29.6], [51.67, 32.65], [48.5, 34.8], [46.29, 38.08]] }] }),
    S(1298, '獄中で語られた旅', 'ジェノヴァ', 8.93, 44.41, 4, ['marco-polo'], ['genoa', 'venice'],
      '1295年、24年ぶりにヴェネツィアへもどった。その後、ジェノヴァとの海戦に加わって捕虜となり、牢で物語作家ルスティケロに旅の話を語った。こうして『世界の記述』（『東方見聞録』）が生まれた。',
      '1295年、ポーロ家の3人は24年ぶりにヴェネツィアに帰りつきます。みすぼらしいモンゴル風の服を着た3人を、家族はだれだかわからなかったと伝えられています。3年後、マルコはライバルの都市ジェノヴァとの海戦で捕虜になりました。牢の中で、同じく捕虜だった物語作家ルスティケロに、東方の旅を語ります。こうして生まれたのが、世界の記述、日本でいう東方見聞録です。',
      { routes: [{ name: '帰国', color: '#8e44ad', pts: [[46.29, 38.08], [39.72, 41.0], [28.98, 41.01], [20.0, 39.0], [12.34, 45.44]] }],
        marks: [{ name: 'ヴェネツィア', lon: 12.34, lat: 45.44 }] }),
    S(1324, '見たことの半分も', 'ヴェネツィア', 12.34, 45.44, 3, ['marco-polo'], ['venice'],
      '解放後のマルコはヴェネツィアで商人として暮らし、1324年に亡くなった。遺言では、アジアから連れてきた召使いのピエトロを自由の身にしている。本はヨーロッパで広く読まれ、のちにコロンブスも愛読した。',
      '牢から出たマルコは、ヴェネツィアで商人として静かに暮らし、結婚して3人の娘をもうけました。1324年、70歳で亡くなります。遺言には、アジアから連れてきた召使いピエトロを自由の身にするとあります。話を信じない人に、私は見たことの半分も話していないと言い残したと伝えられています。その本はやがて、西へ向かう一人の船乗り、コロンブスの愛読書となりました。',
      {})
  ]
}
  ]);
})();
